/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20171129-7","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"厚生委員会","time":"午前１０時１０分～午後 ４時２３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"の１「意見書（案）について」","agenda":"の１「意見書（案）について」","exchanges":[{"speaker":"若林委員","kind":"意見","question":"記書きの２と３について、３番は「東京都」と頭についているので、ここはどちらかに統一したほうがいいのかと。こういう意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"特に３番の「今後予想される国の施策を見据えて」というところで、この意見書提出者に、私と石田副委員長はなりませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"」を行います。 初めに、（１）「第七期品川区介護保険事業計画骨子（案）","agenda":"」を行います。 初めに、（１）「第七期品川区介護保険事業計画骨子（案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからの高齢社会に向けての介護の状況を充実させてほしいと、本当に皆さん、思っていると思うのです。やらない理由も改めてお聞かせいただきたいのと、地域で有志が集まって、その点についてもの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"まだ確定はしていないのですけれども、前回と同様の対応をしたいと思いますので、お渡しできるようにと考えております。説明会につきましては、持参等々でご意見をいただける体制をこちらで用意しているということで、説明会等については予定はしてございません。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会ができない理由と、区民の方が何人か、こちらでやっていただきたいということで、そういう場所を設定しますので、ぜひ説明していただけないかというふうなお願いがあったときには応えていただけないのか、その点についてもの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"骨子案に限らず、ご不明な点等につきましては、常にご相談をお受けする、窓口・電話等でお答えする体制は、常にとっておりますので、説明会というものは予定はしておりません。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"では、区民の側から、場所を設定したので対応していただきたいということに対しても、応えることはできないということか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"今の段階では、そのような対応は考えておりません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ずっと言い続けているのですけれども、前向きにご検討いただきたいということで、改めて要望させてほしいと求めました。今回の事業計画を組むに当たり、どういうふうに捉えて組まれたのかという点について、まずお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"今の段階では説明会等の予定はありませんとお答えした、もちろんこれは我々も対応できませんので、必要に応じて対応はしていくという趣旨ですので。先ほどの答弁の繰り返しになりますけれども、保険者として事業者支援、これからもそのように対応していきたいと考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現場の状況を一番把握しているのがこういう自治体ですから、区からぜひ求めていただきたいと思うのですけれども、それは後でお願いしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"高齢者に関する総合相談をはじめとした対応を行ってきたところで、介護保険制度が始まって、平成１８年度に大きな改正があったと認識しております。何よりも、そのことでサービスの質が低下しないような形で、品川区としてはきちんと配置していると認識しております。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて、条例との関係で満たしていないというところをどう考えられているのか、お聞かせほしいと求めました。改めて、品川区の地域包括支援センター、高齢者福祉課の中にあるこのセンターの人員配置の説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"それから、高齢者福祉課のということですけれども、保健師としましては、実人数、３人です。それから社会福祉士が、準ずる者を含めて１０名、それから主任ケアマネジャーが３名です。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で言えば、私はぜひ保健師を配置していただきたいということで、強力に求めたいと思います。ぜひ情報の公表もしていただきたいと思うのですけど、その点についていかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"若干、情報が古くなっているという実態があるということは、我々も認識しています。公表につきましては、今後もきちんとした情報が伝わるように、適切な公表となるよう努めてまいりたいと考えております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"では、東京都で公表されているような、中身を充実させた形で、品川区のホームページにも公表を今後していくということでよろしいのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"東京都とのタイムラグ等の問題も含めまして、きちんと対応ができるか等も見定めた上で、必要な公表につきましては検討していきたいと考えております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総合事業をやって３年間、今年３年目ですけれど、総合事業の検証というのはされているのかという点についてもお聞かせいただきたいです。報酬に関してはぜひ、私はせめて同額にしていただきたいと思うのですけど、その点についてもの説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"今後の課題につきましては、前回の厚生委員会のときにご説明したとおり、介護予防ケアマネジメントが鍵を握ると考えております。必要な方につきましては、加算で対応しているという現状ですので、現在のところ、見直すという考えはございません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところはぜひ、少なくとも介護報酬まで引き上げるようにということで、ぜひお願いしたいということで要望します。２割負担、３割負担になったことでどれぐらい増収になるのかというあたりも、わかったらの説明を求めました。","respondent":"松山高齢者地域支援課長、寺嶋高齢者福祉課長","answer":"委員がお尋ねの、総合事業の検証のまとめの報告ですけれども、委員会等で、また介護制度推進委員会等で、その都度報告はさせていただいているところですので、その中で検証はできていると考えております。それから３割負担につきましては、まだ具体的な数値がはっきり示されていないので、今の段階で何割というふうに見込むことは現在できません。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私たちも絶対にこういう方向にしないでほしいと思っているところですけれども、しっかりと品川区で検証して、まとめておいていただきたい。このところがなぜなのかということと、今の段階で国平均と都の平均がわかったら教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"先ほどの３割負担の開始日等につきましては、一番肝心な設定のところがまだわかりませんので、これは見込みようがないです。都と国の認定率につきましては、今、手元にその資料がありませんのでお答えできません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１５ページなのですけれども、２番の「介護サービス量の推移と今後の見込み」というところで、その中には見込みとして出るのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"１５ページのサービス量の見込みの中で、もちろん保険料を見込むときの計算では、この骨子案の中のこのページについてはまず総量を見込んで。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"上記の考え方に基づき、その適正な取り崩しを含め検討いただきたい」ということが、書かれているのです。多分、災害のためにと介護給付費の基金をとっておくということはしていないのではないかと思うのですけど、その点についてもの説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"それから保険者が決定すべきものであるという、この２点をしっかりと踏まえた上で、現状に即した形で対応しているというのが品川区の考え方です。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総合事業もここの中に入って、そこのところが考え方としてもどういうふうに変わってくるのかということもお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"その前の１６ページにグラフと表で記載しておりまして、ここの地域支援事業といったところが全体の割合になるものです。７月でしたか、この後の数値はそちらをご覧いただければと思います。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"８ページの上のほうにあるゆうゆうプラザなども厚生委員会で視察などもしましたけれども、お子さんたちもいて、そういうのは全くないのでしょうか。介護予防マネジメント、ケアマネジメントの強化がなぜ課題になっているのか、そこも伺いたいと思います。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長","answer":"虐待しかり、こういった対応が非常に増えておりますので、ケアマネジメントの強化というところが必要になってくるというのが全体的な考え方です。やはり自立支援についての共通理解を深めるということで、自立支援のほうから、逆方向から見たケアマネジメント力の向上を図ることが必要だと感じまして研修をしています。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはり、私たちはまだまだ足りないという立場で求めているのですけれども、第七期ではもうこれしかやらないということなのでしょうか。伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"わかりづらいというご指摘であれば対応も考えるのですけれども、毎年、今後もそれについてはしっかり対応していきたいとは考えております。特別養護老人ホーム１カ所と書いてあるのは、不確定要素を入れることはできませんので、その分については入っていないという内容です。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは９ページだと一番下に出てきますが、これは施策の展開になってしまうかもしれないのですけど、どのようなイメージを持たれているか。この辺、どのような考え方か、概略だけ教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"来年度にもかけまして、現状を把握するという取り組みをやってほしいということで、区の助成金等も活用して支援している事業も進めております。それに伴って、ケアマネジメントが強化されるし、維持されるというところにつながっていくのであろうと考えております。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"確認","question":"介護人材という面から、今のお話をいただいたと思うのですけど、介護しながら仕事を続けていく方。そっちのほうの介護離職ゼロというのが今回出てきていると思うのですけど、そっちのほうについての確認をしたかったのですが。","respondent":"寺嶋高齢者福祉課長","answer":"今年度も１１月１日と８日に、そういう取り組みを、もう何年もやっているというのがまず１つです。介護者教室という名称でいろいろと、そういったこともご案内しながら、区としてできる支援は引き続き続けていきたいと考えているところです。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、現状、区で行っているのと、それから働き方というか企業側に対する働きかけというのも今回出ています。その辺がこの計画の中にどういうふうに盛り込まれているのかという、そこがわからなかったのでとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"今、計画の中で具体的にはお示しできなくて大変申しわけないのですけれども、重要な課題であることは認識しております。１つ変わってくるので、企業も対応が可能であるなどというところの、１つ前に進むのかとは考えております。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自分からすると、その最後の部分が読み切れなかったような部分があったので、それが確認したかったところです。自分がそこまで、短時間の間に読んでいなかったのかもしれないので、その辺をまた教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７月１１日の厚生委員会の中で、この結果と分析というのがどうなっているのかというのを教えてほしいと求めました。そして来年の８月から施行されるという状況になると思うのですけど、その点について、その３点をお願いします。","respondent":"寺嶋高齢者福祉課長","answer":"夏に実施しましたアンケートですけれども、１件でも多くということで、締め切りを延ばしてお受けしたところです。まだ正式に確定とは認識していなかったのですけれども、この段階としては入っていないという、先ほどの答弁と同じ内容になります。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護施設についてはまだ今のところは計画について示せるものがないということなのですけど、ぜひ計画を第七期の中で立てていっていただきたい。これも時間のかかることですので、ぜひそういう方針を持っていただきたいということで要望しておきます。","respondent":"寺嶋高齢者福祉課長","answer":"アンケートにつきましては、ご説明の時期・方法等につきましては、今まだ決まってはおりませんけれども、ご提出いただいたアンケートなので、情報としては何らかの形で必ずご報告できるようにしたいと考えております。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"第六期からの一つ一つ、プロジェクトはそのまま７つということで、しっかり前に進んでいくのだという計画とお見受けいたしました。","respondent":"大串福祉計画課長","answer":"対応する組織といったものもつくっていこうといったところで、どのように、医師会あるいは介護の双方の連携ができるような形で対応ができていくのか。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問・要望","question":"スポットになっていまして、本当に大事だということで、ぜひ進めてほしいと求めました。１つのセクション、要望になりますけれども、ぜひ充実をお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"品川区障害福祉計画・品川区障害児福祉計画（素案）』およびパブリックコメントの実施について","agenda":"品川区障害福祉計画・品川区障害児福祉計画（素案）』およびパブリックコメントの実施について","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"当事者の意見を聞いてほしいということでの請願が全会一致で趣旨採択されて、それを受けて、これも本当にありがとうございました。本当に聞き切れなかった部分があるのですけれども、これを全部まとめたものというのは、ホームページで公開されるようになるのか尋ねました。","respondent":"飛田障害者施策推進担当課長、中山障害者福祉課長","answer":"そして、児童発達支援や放課後等デイサービス、そちらも今回の計画の素案に活かしております。そして、この間のアンケートは、今度またパブリックコメントがありますので、一緒に添えてと考えております。どういった合理的配慮が必要かということも記載していただくことも含めて、事前申し込み制ということで考えてまいりたいと考えています。当日の資料も持ち帰りできるようにということで、今後考えてまいります。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"希望する方には提供していただきたいということで、ぜひ対応していただきたいと思うのですけれども、その点もいかがでしょうか。そのように、素案に対しても合理的配慮という形で対応していただきたいと思うのですけれども、その点もお聞かせいただけたらと思います。","respondent":"中山障害者福祉課長、飛田障害者施策推進担当課長","answer":"品川区地域自立支援協議会ですが、事前申し込みを基本としつつ、当日の会場にもよるかと思いますので、その辺は臨機応変な対応をしていければと考えています。ですので、ワードで読み上げて、聞き取り、リスニングでわかるようにはしたいとは考えております。点字やデイジー版など、要望があれば、またそこも対応する必要はあるかとは考えております。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう少し続けていいですか。１年ごとに、この厚生委員会にも報告していただきたいですし、そのことの確認もお願いしたいのです。","respondent":"飛田障害者施策推進担当課長","answer":"今回のところ全てに合理的配慮を行うというのはなかなか難しいかと思いますが、今後のこともありますので、また検討させていただければと思います。今回、協議会で報告をいたしましたところは、ホームページ等でも公表していきたいと考えております。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"合理的配慮については、本当に自治体に対しての義務づけというところにもなっていますので、ぜひ前向きにご検討ほしいと求めました。","respondent":"飛田障害者施策推進担当課長","answer":"今回、いろいろ団体のご意見をいただきましたので、またこちらを見ていただいて、またそれとともにいろんな意見があると思うのです。そこのところで、いろいろ、パブリックコメントとあわせていただければと考えていますので、配りたいと思います。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう視点を持っていただきたいと思ったのですけど、その点、障害者権利条約の位置づけというところはどう考えられているのか。「計画策定の趣旨」のところの４行目の、もう少し配慮した文言に変えていただきたいというのが、率直な私の思いです。","respondent":"飛田障害者施策推進担当課長","answer":"文面等、少しまだ検討しているところもありますので、それもあわせてまた検討させていただければと考えています。１ページ目の文面というところも、今ご意見をいただきましたので、そういうところもまた検討していきたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"（１）「相談支援の充実と適切な情報提供」の「現状と課題」の９行目に、どう考えられているのかということを、まずお聞かせほしいと求めました。","respondent":"飛田障害者施策推進担当課長","answer":"しおりに関しても、バーコード化や、ホームページに対しましてはテキスト化ということで、今、対応しているところであります。そこの情報の共有のところでは、連絡会等も開きまして、そういう施設の状況とか、そういうところで共通認識をもっていきたいと考えております。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"９％を目指すのが、品川区の場合は２％の６人ということにされているのは、どういう理由からなのか。それから、あと、そういうのとあわせてどういうふうに整えていこうということで考えられているのかについてもの説明を求めました。","respondent":"中山障害者福祉課長","answer":"品川区地域自立支援協議会の中でも、もう少し数字を上げるべきではないかというようなお話もございましたので、再度見直しはしていく予定です。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"整備率が本当に２３区の中で最低レベルで、もっと意欲的に、あまりにも国の方向の９％というふうなことに対しても少ない人数。この共同生活援助というのは、何とかもう少したくさんつくれないのだろうかという思いがしているのですけれど、その点についてもの説明を求めました。","respondent":"中山障害者福祉課長","answer":"なかなか難しい、厳しい現状もあるというようなところは、一方で認識する必要があるかと考えています。グループホームを建設したい、丁寧な対応で、ぜひ区内にグループホームをつくっていただくような方向で働きかけをしていきたいと考えております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"特別養護老人ホームにしてもグループホームにしても、どんどんプロポーザルをかけて、さまざまな社会福祉法人が各県から来ているではないか尋ねました。","respondent":"中山障害者福祉課長","answer":"今回、南品川の児童学園の跡施設についてもプロポーザルで事業者を決定したというのは、１つそういうこともあったと考えています。例えばアパートを改修したり、そういった方法で運営をしてくださるところに助成金を出すというような形で進めていければと思っています。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほかの区にもそういう場合はどうですかと聞いたら、多分、そういう形でできていくのではないかという思いがしています。利用日数では２.７８倍ということになるのですけれども、そこのところからこういう形で出てきたのかというところをまずの説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"区長からも今後、福祉にも、今回の障害児者総合支援施設を１つの糧として区内にも広げていくというところで。そこの事業所の人材のレベルアップというところがありましたので、このように伸ばしています。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成３２年は１０日という形で、これは本当に皆さんがこの日数を増やしてほしいということで、すごく切実な要望もたくさんの方から伺っていますので。","respondent":"飛田障害者施策推進担当課長","answer":"あくまでも見込量ですが、見込量としては、今までのところではこのぐらいかと考えております。ですので、今回またこちらは書き直して提示する予定です。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、これをどこが請け負って、体制をどうとるのかというところもお聞かせほしいと求めました。その辺についてもの説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"新たに保育所等訪問支援を行う事業所等も増えるということも考えられますので、見込量がまた増えていく可能性はあるかと考えております。平成３１年度の障害児者総合支援施設には、検討しているところですので、報告ができればと考えています。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１人１０日というふうなことで、平均でもそういうふうになっているわけですから、ぜひ要綱でも基本１０日はなくしていただきたい。相談事業所で１０日にというのがどうしてもかかってきてしまうという部分がありますので、そういう形で、最後にその点だけの説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"現在、戸越でやっていますコンパス等では、月４回もしくは２回という、利用日数が少ない方もいます。ですので、そういうところもまた鑑みながら、利用者、また保護者と話し合いながら、その人に合った日数の提供をしたいと考えております。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問","question":"どうニーズをしっかりとお聞きしながら、具体的というか象徴的には、各個別に見込量が示されていますよね。相談支援は個々のニーズにしっかり対応できるような支援プランを立てていくという、まず大まかな考え方をお聞きしたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"地域生活支援拠点３カ所ということで、障害者生活支援センター、福栄会障害者相談支援センター、グロー障害者相談支援センターの設置をいたしました。それによって、その人のニーズによって今回の見込量は当然、やはり変わってくるところもあるかと思います。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"次の２２ページの（２）「障害者の高齢化への対応」ということで、何というのですか、理解が違うわけですよね。やはりシステム的な何かがこの際できるのではないかという期待はしているのですけれども、その辺の考え方、方向性を少しお聞かせいただきたい。","respondent":"飛田障害者施策推進担当課長","answer":"介護保険の対応、少し検討しながら、何人かピックアップして想定しているところです。やはり人が変わるとというところもありますので、今後はマニュアルを作って、またそういうところで体制を整えていければと考えております。","id":"exchange-041"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"３ページの品川区地域自立支援協議会なのですが、どんな議論がされているのか報告がされる場所というのはあるのでしょうか。４個か５個ぐらいある部会の報告があって、そういった部会の報告というものがされる、公開というか公表されるところがあるのかどうか伺いたいです。","respondent":"中山障害者福祉課長","answer":"それは、品川区地域自立支援協議会の全体会で報告されることになっています。今回の品川区地域自立支援協議会は、既にさまざまそれぞれの部会で検討したことが、通常の品川区地域自立支援協議会ですと。","id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"部会の方が出てきて報告をされる。報告のされ方というのですか、それを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"例えば相談支援部会は、メンバーがこちらの品川区地域自立支援協議会にも入っていますので、その方が報告しますし、逆に日常生活用具検討部会ですと、行政のほうから、その部会で検討された内容を報告するというようなことになっております。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ということは、多様な事業者の参入というのはどういうふうになっていくのかと。ここの表と文言の関係の説明を求めました。","respondent":"中山障害者福祉課長","answer":"それは、相談支援事業所であっても、多様な事業所に参入していただきたいと思っています。４８ページの「相談支援事業」というのは、地域生活支援事業の中の相談支援事業ということになりますので、いわゆる計画相談ではなく基本相談をやる。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"では、そうすると、２６ページで言っているものと、４８ページで見込んでいる箇所数というのは違うものということなのか尋ねました。","respondent":"中山障害者福祉課長","answer":"例えば４２ページに、計画相談支援という数字が載ってきます。特に就労移行支援などは民間事業所も数多く参入していますので、区内にいろいろな支援の幅を広げていければと考えているところです。","id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"既存事業の再構築、言葉では書かれているのですけれど、これがどういうことなのかというのをもう少し具体的に言っていただけたらと思うのですけれど。全体的に、ここで何をどう具体的にしようとしているのかがわからないので、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"あるいは地域の拠点の相談支援事業所がありますので、そこに緊急対応とか、なるべく未然に対応ができるようにというような形で。は区内の連携によって、２カ所の相談支援事業所と連携しながら、ここの文章はもう一度整理させていただければと考えています。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２９年の６月現在、自立訓練定員６人）となっているのですけれど、この自立訓練というのは生活訓練の間違いではないか尋ねました。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ｂ型のほうですが、例えば区内の今の就労継続支援Ｂ型が２６０人の定員だったとして、そうではありません。瑞宝会のほうなのですが、自立訓練と組み合わせながらショートステイということで、比較的長く利用できる施設とこちらは認識しておりました。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その下の（４）「相談支援」のところなのですけれども、何というのですか、モニタリングで３カ月ごとに計画を見ていくというのがありますよね。","respondent":"中山障害者福祉課長、飛田障害者施策推進担当課長","answer":"実際のプランをつくっている人の数というところですが、おおむね１,３００人ほどになっているかと思います。これは大人の数だけになっています。地域移行支援のほうで、せんだっての品川区地域自立支援協議会で、ｂ「見込量の確保等にあたって」の書きぶりのところで指摘がありました。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"「計画相談支援」のところの実際の数が１,３００人ということなのですけれど、障害者の福祉サービスの利用者は、これを含むということになると思うのですけれど、そうすると、サービス利用者が１,３００人ということで考えていいのか確認をお願いします。","respondent":"中山障害者福祉課長","answer":"地域生活支援事業は必要ないということになっておりますので、障害福祉サービスのご利用者数と考えていただければと考えています。","id":"exchange-049"}]},{"id":"topic-04","title":"平成３０年度からの国民健康保険広域化の動向等について","agenda":"平成３０年度からの国民健康保険広域化の動向等について","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて教えていただきたいのが、法定内繰り入れと法定外繰り入れということで、その繰り入れというのは赤字分というふうなことになると思います。法定内の繰り入れというのがどういうものがあって、幾らぐらいになるのかということについての説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"その関係の部分、葬祭費等を含めまして、そのあたりが割合の比率の中で法定外の中に入っていく部分があります。国からは３分の１という決まった割合がございまして、決まっている部分が、法定内繰入金として算定されております。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"法定内繰り入れの項目についてみたいなものがあるものなのか、その辺のところが。法定内繰り入れの項目と、あと品川区では法定内繰り入れというのが幾らぐらいなのかという点についてもの説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"今回、手元に決算資料を持っていませんので、申しわけありません。たしか４０億円程度が法定繰り入れ、法定内と外を両方合わせたものでございまして、その中の１５億円程度が法定外繰入金となっております。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今までが１２万３,０００円ぐらい。その辺のところでの２３区での方向というのは、わかっている範囲での状況というのをお答えいただける範囲でお願いできたらと思いますとの意見を述べました。","respondent":"三ッ橋国保医療年金課長","answer":"この中には、なかなか激変緩和の部分なども入っていないと思います。試算として、東京都からの試算が出たということは事実ですので、１６万円ということは事実としています。","id":"exchange-052"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その辺のところの活動の中身というのを改めて教えていただきたいのと、どれぐらいの人数とメンバーなのかということについての説明を求めました。","respondent":"大串福祉計画課長","answer":"通常、第２層協議体にも参加していただいている顔ぶれといいますか、そういった事例をもとに検討等々進めていければと考えているところです。個別のところでも、また話し合い等々が進み、ひいてはその地域全体の支えにつながっていくのではないかと考えているところです。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その課題をどういうふうにして、ある力を出してもらうかみたいな方針というのですか、そういうのもつくりながらやっていくということになるのか。その辺の取り組みあたりもお聞かせいただけたらと思います。","respondent":"大串福祉計画課長","answer":"居場所につきましては、引き続き検討していければと考えています。我々のほうでも、ご相談いただければ、そういった中で可能な限り対応させていただければと考えています。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"意見","question":"平成２９年度の支え愛活動推進委員会を１月にやったときに、第２層の進捗状況や課題の報告をしたとあるのですけど、少し出してもらえるのかと思ったとの意見を述べました。","respondent":"大串福祉計画課長","answer":"来年予定している第１層協議体、支え愛活動推進委員会。これにご参加いただいている高齢者クラブのメンバー等々を通じて、そういったアプローチもしていければと考えているところです。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、いろんな面で広げていっていただきたいと思うと同時に、どうしても同じ方がメインになってしまう。それも我々も気をつけないといけないのだけど、やはりそういう方をどんどん増やしていってもらいたいと思いますので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"どういうふうにやっていくのかというところを教えていただきたいのと、あと住民主体で進めていくというところが協議体としてあるのですが、なかなか。","respondent":"大串福祉計画課長","answer":"私ども、出席させていただいて、いろいろご説明しています。その地域の課題といったものを見きわめていければと考えていますし、品川区、支え愛・ほっとステーションを含めて全１３地区にオープンできました。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"なかなかその後、こういうのが逆にきっかけになって進んでいくなどというのがあればいいかと思いますので、ぜひ頑張ってほしいと求めました。１点、裏面の支え愛活動の、これは、第１層と第２層が、大井第二や荏原第二などで行われているということでいいのでしたか。","respondent":"大串福祉計画課長","answer":"その区分けになりますので、大崎第一などで行われているものが、第２層の協議体の活動という形になります。ワークショップなどといったところで、事例を出させていただいたです。","id":"exchange-058"},{"speaker":"大倉委員","kind":"質問","question":"１回、助け合い体験ゲームやグループワークなどというのがやられている中で、これはどういうふうに開催していくのか。それが、今、３地区で、これは１３地域できるのかなどという、その辺の見通しや考え方についての説明を求めました。","respondent":"大串福祉計画課長","answer":"大崎第一については、今回、こういった取り組みをしていただけるということで大変ありがたいと考えています。例えばほかの地区で、なかなかどういう展開をしたらいいのかと迷われているところのいい参考例になるのかなと考えているところです。","id":"exchange-059"},{"speaker":"若林委員","kind":"質問・要望","question":"１日の時間帯によってデスクワークがあったり、実態として、１３地区で２６人ですか。お話を伺うということはあるのですけれども、動きとして果たしてどういうふうなことをされているのかということ、ぜひ教えていただきたいと。","respondent":"大串福祉計画課長","answer":"そこに相談者が来れば、その対応をするといったところ。１日、本当にケース・バイ・ケースになってまいりますけれども、そういった形で外に出たりといったところが１日の流れとなろうかと思います。","id":"exchange-060"},{"speaker":"若林委員","kind":"質問","question":"地域づくりですか、逆にこちらが２つの大きな柱とすれば、もう一つの期待される大きな役割があると思うのです。これからどういうふうに、また区としても、これは大きな意味で今後の構想や取り組みをお聞きしておきたいと思います。","respondent":"大串福祉計画課長","answer":"あるいはこうしようというところではないというのが、この事業のポイントであり、一番難しいところだとは考えているところです。我々としても、皆さんと一緒に考えながら進めていきたいと考えているところです。","id":"exchange-061"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"すごく１３地区それぞれで、先ほどの第２層協議体のところでおっしゃられた人数は、ここにはボランティアは入っていないということですか。そしてまた、課題などがあれば教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"例えば平成２３年から始めた品川第二でいけば、支援員が、平成２８年度のときには５０人の方に登録していただいていました。それから、大崎第二が平成２７年度に開設したのですが、こちらが平成２８年度のときの支援員の登録数としては３６人といったところです。","id":"exchange-062"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういうコーディネートするのがコーディネーターなわけですけれど、この資料で、生活支援コーディネーターは２人常駐している。１３地区に常駐している２人の社会福祉協議会の職員とはまた違って、もう一人、リーダー的な人がいるということか尋ねました。","respondent":"大串福祉計画課長","answer":"統括ということで、１３地区をまさに統括する立場の方です。本当に各地区２人、２６人の統括的な立場、お１人選任していただいているです。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":83180,"voices":171}},{"id":"h29-20171129-8","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"建設委員会","time":"午前１０時０８分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件整理しています。","topics":[{"id":"topic-01","title":"京浜急行本線連続立体交差化計画及び関連する道路計画の都市計画案等の説明会の開催","agenda":"京浜急行本線連続立体交差化計画及び関連する道路計画の都市計画案等の説明会の開催","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"高架化について伺いたいのですけれども、高架化での立ち退きの件数を教えていただきたいのですが、人数もわかれば教えてください。そうした方々への説明や意見は聞いているのか、どんな反応があると聞いているのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"今後、測量等を実施いたしまして、東京都のほうで確定をしていくものです。現在、つかんでいる情報は、区のほうでは持ち合わせてございません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"その住んでいる方にものすごい影響がある計画なのに、つかんでいないということでよろしいのでしょうか。線路の真上での高架化計画にならなかった理由は何なのかということを伺いたいのですけれども、また、幾つかわかれば紹介していただけないか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"説明会がここに記載してありますとおり、１２月に予定してございまして、権利者の確定をするというふうに聞いてあります。難しいといいますのは、ちょうどその跨線橋のところにあるトラスにかかってしまうというような状態だというふうに聞いております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の右側に振った計画になるにあたって、京急側の要望はあったのでしょうか、なかったのでしょうか。お伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"地下化にするかという部分につきましては、東京都、京急とあわせ持って検討をした結果としてのものというふうに聞いてあります。京急側から直接要望があったというよりは、どういう形での構造が望ましいかという検討の中で高架化になったというようなものです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"京急側の要望があるかないかは、よくわからないということだと思うのですけれども。検討と説明を強く都に区から求めてもらいたいのですけれども、求めていただきたいのですが、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"まさにその説明会をする場が今回の都市計画案の説明会です。こちらにつきましては、本年１月２７日、２８日におきまして、素案の説明会の中でも東京都が住民に対しての説明をしています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明してもらいたいというか、再検討もするということもやはり要望してもらいたいのですけれども、ぜひそれをお願いしたいと思うのです。私ばかりやってもあれなので、一旦やめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"ご説明とこの文書で距離とかはわかるのですけれども、今回の説明会で、イメージを使った説明とかはなされるのでしょうか。何かイメージ図とかを提示していただけると非常にわかりやすいのですけれども、その点、今回の説明会はどうなっているのかおわかりか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましても、区民の皆さんがわかりやすい説明がなされるという予定です。まだでき上がっていないのですけれども、パンフレット等も当日配布する予定がありますので、そちらをあわせて説明を行う予定と聞いております。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"正確な測量についてはこれからにせよ、この図を見ると、ある程度、線が引っ張ってあるわけですから。情報の共有化については、どう考えられて、どういう現状になっているのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"東京都との情報につきましては、一定程度の情報共有をした上で説明会を行うという立場です。立ち退き者、ご協力いただく方が確定していくという段階だということで、具体的な人数とか権利者の数とかについては聞いていない状況です。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"そういう話はまだしていないということでいいのですか。もうしているということでいいのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"具体的な権利者の確定とかにつきましては、事業主体の東京都が進めているという段階でございまして、私どもは確定した数字は聞いてございません。そういう中ですので、今回、説明会等で具体的にそういうご質問があれば、東京都のほうからお答えするような形になろうかと思います。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"そこら辺を東京都がやるにしても、品川区に責任もあるので、しっかりやっていただきたいと考えていますので、区の考え方もお知らせください。その方々とのやりとりはどこまでいっているのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"駅前広場の進め方なのですけれども、こちらにつきましては、東京都の説明会と同じ手順で都市計画手続を現在進めているところです。その中で地権者の方もいらっしゃっておりますので、ご意見を伺っている、そういう段階です。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりせっかくの広場ですから、皆さんの意見が詰まった広場にこれからなるのでしょうから、期待を込めて丁寧な進め方をお願いしたいと考えています。それに対して何かありましたら。","respondent":"東野まちづくり立体化担当課長","answer":"地域のまちづくり協議会、または再開発協議会などを通じまして、意見交換をさせていただいているところです。今後も意見交換の予定をしておりますので、そういった中で区のほうで丁寧な説明を続けていきたいと考えています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"駅前広場のことについて、もう少し具体的にお伺いしたいと思います。それと、地域の方のお声は、どんな声があるのかということを教えてほしいと求めました。","respondent":"東野まちづくり立体化担当課長","answer":"１月に行った素案説明会の時点では、まだ区画といいますか、この範囲が決まっているものではございませんでした。そういった要望書も品川区長宛て、東京都知事宛てにもいただいているところです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に１点ですけれども、この今示されているものが、ほぼ計画として進んでいくということでよろしいのでしょうか。もうちょっと狭くならなかったのかとか、ここまでこうやって広くされている、もう一度そこの意義といいますか、それを教えてほしいと求めました。","respondent":"東野まちづくり立体化担当課長","answer":"図を見ていただければわかるとおり、東側だけでなく、西側にも乗降の状態を考えまして、たまり場等も考えた上での形となっているものです。この計画につきましては、今後、この形で都市計画手続を進めたいというふうに考えてあります。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"広場について伺いたいのですが、交通広場と言っていたのですけれども、区画街路第７号線といつの間にか道路計画になっているのはなぜなのか。地名で言うと、この道路はどこなのかということをお伺いします。","respondent":"東野まちづくり立体化担当課長","answer":"区画街路第７号線は、この駅前広場をつくる目的といたしまして、道路の名称です。この駅の南側、ちょうど区画外、図の一番南側のところ、直線になっていると思うのですけれども、こちらは１２ｍの道路がすりつくような形になります。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ道路の名称になるのか全然わからないのですけれども、しかも、１２ｍと言いましたけれども、これは相互通行ですか。ここになぜ道路をつくるのかの説明を求めました。","respondent":"東野まちづくり立体化担当課長","answer":"こちらは１２ｍの道路につきましては、相互通行となります。一般車も含めて、こちらのところに入ってくるということになりますので、道路が必要というふうに考えてあります。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"しかも品川駅からものすごく近いですから、なぜそのような交通広場が必要なのかということで、全然要らないという声が多いわけです。普通に考えたら、駅広場という案は引っ込めるべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"９０％以上の方が徒歩で今現在使われているという状況は、障害者用の乗降場、そういったものを設ける必要があるというふうに考えてあります。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺はどうなっているのですか。区の意思疎通といいますか、縦割りなのですか、そこら辺をもう一度お伺いします。","respondent":"東野まちづくり立体化担当課長","answer":"その町会での勉強会につきましても、私どもの考え方について示させていただいて、意見交換をさせていただいているところです。今後も意見交換の場をつくっていきたいと考えています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"この道路をつくることで、今回の説明では全くないのですけれども、それは特に理由ではなかったということなのでしょうか。その２点をお伺いします。","respondent":"東野まちづくり立体化担当課長、藤田都市環境部長","answer":"国道側へ抜けていく車が、その先の北一会館の前を通って抜けていく車が６００台ほどございました。タウンミーティングの当日のお話もありますので、私のほうからもお話をします。担当課長が先ほど来ご説明させていただいているとおりですけれども、まちづくりの将来性、そういったことも含めながら。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"現行では、その２００ｍほどの流入交通の解消のために、それほどの人を立ち退かせてまでやらなくてはいけないことなのか伺いたいと思います。こういうのが区の方針なのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"交通流入の解消につきましては、１つの理由になるかというふうには考えているところですが、そればかりではございません。区の方針につきましては、今回、地元の方にも丁寧な説明を今後も続けていきたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"指摘したいのですけれども、今回の区画街路７号線という計画をさらに東側に延長して、八ツ山通りまでの道路の新設の絵がかかれているのです。","respondent":"東野まちづくり立体化担当課長","answer":"現在の道路形状を考えると、そういった警察との協議もしているところで、旧東海道のところでとめているような状況です。この道路が完成するということではなく、地域のネットワーク全体を考えた上で、やはり必要な道路ではないかと区のほうでは考えているところです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"新設道路の要望はもらっているということですけれども、伺いたいのは、今回の道路をつくると、将来的には再開発にプラスになるでしょう。","respondent":"東野まちづくり立体化担当課長","answer":"再開発協議会が立ち上がって、現在、その再開発のコンセプトづくり等をしています。こちらにつきましては、地域の再開発をどう考えていくかというところを現状進めているところですので、そういうご理解をいただきたいと思います。","id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"どうなるか、そして年明けに都市計画審議会を開き、そこで都市計画決定がされる。区の元まちづくり部長などが、学識経験者と称して２名入っていて、そうした多数で……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"だから、私が伺いたいのは、今回の国交省の都市計画法運用指針、公聴会を開かなくてはいけないのではないですかということが言いたいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"まさに必要があると認めるべき案件であって、公聴会を行うべきではないでしょうか。少なくとも公聴会を開いてから案を作成すべきだと思いますけれども、私は国交省のこの指針違反だと思いますけれども、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"２回ほど素案説明会、今度行う都市計画案の説明会ということで、住民に対して２回の説明を行います。意見書の提出期限、公告・縦覧の期限も設けておりますので、そういった中での対応が可能だというふうに考えてあります。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"公聴会を開くつもりはないという、その品川区の対応は、私は国交省の指針違反なのではないですかと聞きましたので、しっかりとお答えください。違反なのではないか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"この公聴会等の中には、こういう説明会も含まれているというふうに解釈しています。違反とは考えてございません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"これは明らかに違反なのではないですかと思うのですけれども、いや、これまで区がやってきた対応とも矛盾するのではないですか。いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"冒頭の説明でも申し上げました今度行われる説明会につきましては、地権者の方にもご案内をする予定です。こういった公の説明の場で、都市計画案について、駅前広場については説明をしていくという予定です。","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"それは絶対にそうした対応は改めるべきだと思います。何かご意見がありましたら言ってくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"間違いなく京急の北品川、新馬場の駅周辺の活性化が図られて、よりポテンシャルが上がってくるということです。ちなみに、ここのまちづくりと、将来行われる、３０年ぐらいでしょうか、リニアとの関連性についてお伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"リニア中央新幹線につきましては、品川駅の地下に駅が新設される予定です。そういった意味でも、活性化をこの地域で取り組んでいくべきものというふうに考えてあります。","id":"exchange-027"},{"speaker":"大沢委員","kind":"質問","question":"それから約１１カ月、１月の素案の説明会を踏まえての今度の説明会、どのような意のもとに今回の説明会を行うおつもりでしょうか。そこのところの意気込みといいますか、臨む姿勢についてお伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"素案説明会、それから都市計画案の説明会につきましては、都市計画手続の中で進められているものです。今回の説明会では、エリアの確定したものとしまして、住民の皆様にコンセプト等々ともに説明を行うものです。","id":"exchange-028"},{"speaker":"大沢委員","kind":"質問・要望","question":"住民に理解をしていただくように進めていただきたいのですけれども、そこについてお考えがありましたら、お願いします。","respondent":"東野まちづくり立体化担当課長","answer":"説明会は、都市計画案という形での説明会になってあります。今後続けていきたいと考えていますし、地域の方に理解をいただきたいという思いで、駅前広場については進めていきたいというふうに思っております。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは３カ所の踏切が除却されるということですから、非常にここの部分についてはまちの活性化、しっかりとしたまちづくりをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"いながわ副委員長","kind":"質問","question":"多分、地域の方からいろいろなご質問等もあろうかと思いますので、そこはしっかり真摯にお答えをしていただければという思いがあります。どういう感じでかかわっていくのか、実際はどのような感じなのか、簡単でいいですから。","respondent":"東野まちづくり立体化担当課長","answer":"東京都の踏切対策基本方針で開かずの踏切の解消でありますとか、その中に位置づけられているものを事業化していくものです。この間、強くしてきたところでございまして、事業主体である東京都と一緒になりまして進めていくという立場です。","id":"exchange-031"},{"speaker":"いながわ副委員長","kind":"質問","question":"やはりこの旧東海道の最初の宿がある品川宿ですから、どういう形にするかとかというのは、その辺はどう……。全員が全員そうかどうかは別にしても、僕は有益ではないのかという考え方なので、どうお考えか。","respondent":"東野まちづくり立体化担当課長","answer":"そういったところも踏まえまして、景観上のしつらえとかにつきましては、京急のほうへ区としていい形での要望を上げていきたいと考えています。東京都、京急のほうには、区としては伝えていきたいと考えています。","id":"exchange-032"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"最後に、本当に初歩的なことなのですが、品川区画街路等７号ということは、７本目という、そういうイメージなのか。いろいろ調べると、区画街路で出ているのですけれども、イメージが沸かないので、例えば、品川区でほかにどういうところがありますか。","respondent":"東野まちづくり立体化担当課長","answer":"区決定の道路という形になりまして、区画街路という名前では、私のほうでは記憶がないところなのですけれども……。","id":"exchange-033"}]},{"id":"topic-02","title":"防災行政無線設備更新工事","agenda":"防災行政無線設備更新工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"更新の順番の考え方を１点お伺いします。例えば、ちょっと聞こえづらいという問題もあちこちから出ていたと思うのですけれども、そういった不具合などは解決になるのかをお伺いします。","respondent":"古巻防災課長","answer":"公園に設置されたもので、独立して支柱が立って、更新に際して周辺にあまり影響がないところから始めていくということで考えております。拡張性を持たせて、いろいろな情報機器との連携が柔軟に行えるようになったりとか、そういったところもメリットとして考えているところです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"意見","question":"地域の町会ですとか、そういった方々のお声も極力聞きながら、実態をつかみながら改善につなげてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"新妻委員","kind":"質問・要望","question":"１５０局と入っておりますけれども、どういうところにつけるのか教えていただきたいのと、この防災ラジオの考え方を少し教えてほしいと求めました。","respondent":"古巻防災課長","answer":"完全にデジタル化をしますと、今の仕組みの中では防災行政無線の出力ということでは難しい、そのままでは使えないような状況になります。デジタル化が完了するまでに検討を進めまして、場合によっては機器を交換するとか、そういった形での対応を考えているところです。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、戸別のところ、確認させていただきました。これは私立保育園は毎年拡大をしていただいておりますので、新設でできるところは、そのときにつけていただけるということでいいのか尋ねました。","respondent":"古巻防災課長","answer":"つけているところと、一部ついていないところがあるのかというふうに認識をしているのですけれども、必要に応じて対応を考えていきたいと思います。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"５,０００個ですから、たしか５,０００円かそのくらいしていたような気がするのですけれども、議員は全員買ったと思うのですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうことも含めて、割引にするのか、それによって経費も対応していかなければいけないと思うのですが、それもあわせて今後検討してほしいと求めましたが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"あっ旋等を含めまして、どういった形でやるのかはこれからの検討になりますので、今いただいたご意見も参考にさせていただきながら、今後、十分検討していきたいと思います。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"先ほどご答弁に、今回の更新によって、音は聞こえよくはならないのか尋ねました。","respondent":"古巻防災課長","answer":"デジタル化によって、何か聞こえやすくなるということと直接的な関係があるわけではないということで申し上げたところです。取りつけの位置ですとか方向、そういったものを細かく調整することで、できるだけ聞こえやすくということは努めてまいりたいと考えております。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"音量の問題とかもあると思うのですけれども、やはり満遍なく幅広く聞こえさせるためには、具体的にどういったことが必要なのでしょうか。１カ所のスピーカーの数を増やすとか、そういったことも必要なのか尋ねました。","respondent":"古巻防災課長","answer":"スピーカーの数の調整でありますとか、１カ所につけるスピーカーの方向、どの方向につけるのかといったところ。周辺の状況を踏まえながら、設置する機器でありますとか、設置の方向等を調整をしていくというような形になろうかと思います。","id":"exchange-041"},{"speaker":"いながわ副委員長","kind":"質問","question":"１５２局つけているわけですから、同じ方向に向いて一斉にしゃべったら、真ん中にいる人は何を言っているのか全くわからなくなってしまうのですね。もう１点は、聞こえのいい配置を実現してもらいたいと思うのですが、何かあれば。","respondent":"古巻防災課長","answer":"は音響として聞こえやすいようにということは心がけて努めていきたいと考えております。代替手段、ほかの何か機器によって放送の内容が把握できるような何かそういったものも含めて、全体の仕組みを考えていきたいと思います。","id":"exchange-042"},{"speaker":"大沢委員","kind":"質問","question":"そこで、音ですから、耳の不自由な方、あるいは、今、外国の方も増えていらっしゃる。この方に対してどのように対応されていくのかの説明を求めました。","respondent":"古巻防災課長","answer":"それから耳がそもそも聞こえづらい方に対しての対応ということでいうと、やはり文字情報で出せるような形のものが一番いいのかと思います。具体的に今これということで仕組みの導入を考えているものはないのですけれども、今後、さまざまな検討をさせていただきたいと思います。","id":"exchange-043"}]},{"id":"topic-03","title":"品川区地域防災計画の素案","agenda":"品川区地域防災計画の素案","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"避難所のところで大事だと思って何度か提案させていただいていたのは、段ボールベッドに対して、それはどこら辺に入っているのか教えていただきたい。その他（事故）の１ページなのですけれども、これはどういうことなのか、もう少し教えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、まだまだ弱いのかということを１つ指摘をさせていただきたいのと、ここでいう区が果たす公助の役割というのは何なのか伺いたいと思うのです。","respondent":"古巻防災課長","answer":"また落下物が起きた場合でも対応が必要になってくるケースが考えられますので、こういった形の記述をさせていただいているです。公助がきちんと連携をして災害に対応していく、防災力の高度化、品川区の責務ということで条例にうたわれている内容そのものだと認識をしております。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"なぜ認めないのかというか、別にそこを認めたからといって、なぜそれをかたくなに認めようとしないのかというのが逆にわからないと思ったので……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"第２に共助、伺ったのは、まず個人や地域社会に対応してもらう。解決できない問題について区が対応するというのが公助と言っているのですかと伺ったので。","respondent":"古巻防災課長","answer":"支援をしていくということは当然ありますし、いろいろな情報を発信し啓発に努めていく、共助をバックアップするというのが１つの大きなこと。耐震化を進める、そういったハード対策も含めて、公がしなければならないことをきちんと果たしていくことが公助と考えております。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"震－１－８ですか、それを求めたいのですけれども、いかがでしょうか。私はこの考えは修正すべきだと思いますし、そうしてほしいのですけれども、なぜ超高層の再開発が震災対策といえるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"だから、私は、なぜ超高層イコール、再開発イコール防災機能の促進になるのか。なぜそう言うのか、ここはお伺いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"やらないとおっしゃるのでしょうけれども、なぜやらないのでしょうか。それ以上に私たちの命と財産にかかわる計画ですから、この計画の内容を説明する説明会をやるべきだと思うのですけれども、いかがか尋ねました。","respondent":"古巻防災課長","answer":"説明会でということではなく、パブリックコメントできちんと公表いたしまして、それに対して意見を求めていくというようなことで考えております。お問い合わせいただければ、説明会を開いてということで、今のところ予定をしているものではございません。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜやれないのか、やる意思がないのか、説明したくないということなのでしょうか。私は説明会をやらないというのは、積極的な説明をしたくないとしか思えないのですけれども、そこら辺は、やらない理由をお伺いします。","respondent":"古巻防災課長","answer":"地域防災計画自体につきましては、防災会議で確定をしていくものですので、その中で丁寧に説明をすることが大事かと考えています。丁寧に啓発を進めていくですので、防災計画自体についての説明会は、今のところ必要はないと考えているものです。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"どちらなのでしょうか。それだけ伺いたいと思います。","respondent":"古巻防災課長","answer":"特にパブリックコメントと説明会をセットでやる仕組みがあるわけではありませんので、状況に応じて説明会をする場合もあるし、必要性は薄いのかということで開催させていただかないというような判断をさせていただいたです。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"震－５－８で、(1)として、どのようにお考えなのか尋ねました。","respondent":"古巻防災課長","answer":"防災ラジオということで、防災行政無線を補完する手段が確保されておりますので、その形の中で書かせていただいたというような形です。時点修正等もかけていきますので、場合によって、そのときの状況に応じた記載に改めていくというような形になります。","id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"２点ほどお伺いいたします。存続の要望をしっかりしておりますので、区からもぜひお願いをしてほしいと求めましたが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"今後、「ローリングストック」でありますとか「循環備蓄」、そういったよりわかりやすい言葉での周知も含めて検討させていただきたいと思います。","id":"exchange-055"},{"speaker":"横山委員","kind":"確認","question":"こちらは具体的にどういう意見が反映されて、どういった環境を整えるといいというようなことになるのでしょうか。教えていただけたらと思います。","respondent":"古巻防災課長","answer":"そういった中で防犯、プライバシーの確保等に資することができるような避難所の環境整備を進めていくということで、例示として挙げさせていただいたということです。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問","question":"暗い場所だったり、誰も人気がないような場所をなるべくつくらないようにしていくという、そういう意味でよろしいのですか。女性だったり男女共同参画の視点から、そういった意見があって反映されてきたということで理解はよろしいのか尋ねました。","respondent":"古巻防災課長","answer":"なるべくそういったストレスが少ない状況で生活ができるような環境を整えていくということで、男女共同参画というだけではありませんけれども、特にご意見をいただいた部分について書かせていただいたです。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"それの資料編も新しくなるのでしょうか。そこら辺をまずお願いしたいです。","respondent":"古巻防災課長","answer":"初動体制マニュアル等、その下の具体的な動きの部分についてはマニュアルとして整備をしていくというような整理で考えていただければと思います。当然、今の防災計画にもありますので、それは最終的にはきちんと整理をしていきたいと考えております。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"それは大きく変わらなくても、変更点とかというのは、随時やっていくという認識でいいのですか。このマニュアルの防災計画の見直しは、何年ごとにとか、そういう大枠があるのか尋ねました。","respondent":"古巻防災課長","answer":"人口でありますとか、資料編のほうで記載をいたしまして、そこを差し替えていくような形で変更を加えていくというような形で考えております。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"実際のマニュアル等々とか、それから、そこら辺の整合性をきっちりと現場に則した形でやっていただきたいと考えています。そこら辺はまた運用の部分で今後検討していただきたいと考えていますので、これは要望として言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"いながわ副委員長","kind":"質問","question":"それに全部周知して、みんなが同じ考えの中で最低限備蓄するということが一番美しいのですが、本当に周知ができるものなのですか。本当にどうなのかということにちょっと疑問を感じてしまったので、必要があるかどうかというのは個人の考え方なので、実際はどうなのか。","respondent":"古巻防災課長","answer":"備蓄の考え方ですけれども、そこをさらに進めて備蓄についてきちんと必要性を周知をしていきたいというような書き方をさせていただいてあります。","id":"exchange-061"},{"speaker":"いながわ副委員長","kind":"質問","question":"家族４人で、備蓄の量はどれぐらいになるのですかと、イメージがおそらく家庭でわからないような気がするのです。だから、そういうところで一人でも多くの目に触れるところに、そういった取組みをしていってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-04","title":"本日は、防災対策に関することのうち、都市型災害","agenda":"本日は、防災対策に関することのうち、都市型災害","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その活動困難地域の存在と、この拡幅整備の事業の関連といいますか、そういうものはどうなっているのかお伺いしたいと思うのが１点です。広げるべきだと思うのですけれども、区内全域にこれを広げられない理由があるのか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"防災広場の設置に伴う貯水槽の設置等で消防活動困難区域を少しでもなくしていこうということで、取組みを現在も推進しています。早急な対策、改善が必要なところから、改善を目指してやっていくものであると考えておるところです。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"燃えなくなるわけですから、私は重層的と言っていますけれども、一番重点的にやらなくはいけないと思うのです。私が伺ったのは、区内全域に広げられない理由はあるのですかと伺ったので、お伺いします。","respondent":"高梨木密整備推進課長","answer":"このように考えていますので、また必要なところには計画を立てて事業を入れていくということを今後も積極的にやっていきたいと考えているところです。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"ぜひそうしていけないのかというか、それが必要なのではないかと思うのですけれども、それをできない理由をもう一度お伺いしたい。それと、道路は、２９号線が延焼遮断ということはここには出ていないのですけれども、それはなぜなのか尋ねました。","respondent":"高梨木密整備推進課長","answer":"５年先だと思っていたものを前倒ししてやろうという方を１人でも多くつくって、そのような考えのもと、不燃化特区等の事業を進めているところです。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"これはどういう調査をしているのかわからないのですけれども、私が求めているような耐震化、そこら辺はしっかりお伺いしたいと思います。それだけ言うわけですからお答えいただきたいのですけれども、道路は防災性があるのですかと質問しても、重層的にやると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"この車両火災についても、実際はどう考えているのですか。しっかりお答えいただかないと、防災のための道路と私は言ってほしくないと思うのですけれども、いかがか尋ねました。","respondent":"高梨木密整備推進課長","answer":"防災広場の設置等、また住民との話し合いの中で進められていくものと考えておりますので、現在としては決定されたようなものはございません。火を食いとめるということで、道路と並行して防災上必要な取組みであるということで考えており、進めているところです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"なぜ延焼遮断になるのですかと伺ったのと、それは想定しないで、なぜ延焼遮断になるのですかというお答えがなかった。だから、そこに関しても、風向きに関してもどう考えているのか尋ねました。","respondent":"中村都市計画課長","answer":"その２つを重層的にやることで、そういった過去の阪神・淡路大震災の実績などからもいえることを、これから品川区内でもやろうです。かといって、そういった可能な限りの努力をするという意味で、重層的にこれからも行ってまいりたいというふうに考えております。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"東西の風についてはどうなのでしょうか。それに関してマイナスの面についてはどのように考えているのか尋ねました。","respondent":"中村都市計画課長","answer":"所管事務調査ということで説明を申し上げておりますので、江戸の町が約６割を焼失した、そういった火災の展示がされておりました。これからも引き続き、地域の皆様の声を聞きながら、にぎわいを継続していければと考えております。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"全ての説明を伺っていると、防災のための計画ではなかったですから、本当にむりやり道路をつくるための説明にしか聞こえない。これは見直していただきたいというふうに思いますし、大変なところに住宅の耐震化、不燃化を進めるべきなのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"その期間を過ぎてもめどが立たないといった場合の見直しはするのでしょうかというところが１点目です。この助成事業、これ、実績はどのような感じなのでしょうかということで、現状の説明を求めました。","respondent":"高梨木密整備推進課長、持田河川下水道課長","answer":"はこのまま自然の建替え等で目標が達成する見込みとなれば完了となりますが、継続した取組みが必要であるということであれば、これからもそのように総合的に考えて進めていきたいと考えております。防水板の設置につきましては、昭和６２年より実施してございまして、これまで１４８件助成をしている。雨水タンクにつきましては、平成１８年から実施いたしまして、１７３件助成をしているです。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"何か１枚ペラでも、より皆さんに実感していただけるのではないかと思ったので、工夫していただきたいと思いました。私たちも推進をしていく必要があるかと思いましたけれども、今後も機会があったら、積極的にＰＲ等々していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594236?Template=document&Id=4220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":63295,"voices":175}},{"id":"h29-20171129-9","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"文教委員会","time":"午前１０時０９分～午後１１時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"平成３０年度入学希望申請の状況","agenda":"平成３０年度入学希望申請の状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回抽せんになった学校と、ならなかった学校は、昨年と変わっていると思うのですけれども、その理由について伺いたいと思います。","respondent":"有馬学務課長","answer":"抽せんとなった学校、ならない学校ですけれども、今回抽せんとなった学校１４校のうち、昨年に引き続き抽せんとなった学校が１２校あります。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"今回は小学校のほうですけれども、１４校の中で、兄弟枠すら拾えなかった学校がどこか、また何校あるのかを教えていただきたい。戻る子のことも考えているということは今年初めてだったのか、過去にもそういう形で抽せんをやってきているのか、まずその点の説明を求めました。","respondent":"有馬学務課長","answer":"中学校のほうは、全体として１２名おりましたが、１１名受入れて、日野学園の１名だけが待機となっております。昨年も若干そういう傾向がありましたので、その辺は昨年も戻る子を勘案しながら、抽せん結果で待機にしてもらったという例があります。","id":"exchange-002"},{"speaker":"渡部委員","kind":"意見","question":"ではそれをどうするかというのは、選択制は２割強から３割の方がなさるわけで、難しいところです。その辺教育委員会としてお考えになっているところ、何か見解があれば、一言お願いできますかとの意見を述べました。","respondent":"有馬学務課長","answer":"学区域を含めた検討ということですけれども、例えば、場合によっては４クラスということも考えていかなければいけないという逼迫した状況もあります。学校選択制も含めて、我々もそういった議論を踏まえながら、また検討を進めていきたいと思っているところです。","id":"exchange-003"},{"speaker":"渡部委員","kind":"質問","question":"説明を伺いまして、よくわかりました。地域のご理解をいただきながらやっていかなければならないことが多々あると思いますので、大変でしょうが、引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"これは教育委員会としてはどういうふうに評価しているのかを伺いたいと思うのです。正しい見方なのかどうかも含めて、いろいろ見解を伺いたいというのがまず１点です。","respondent":"有馬学務課長","answer":"冒頭にちょっと説明させていただきましたけれども、もう希望申請は出さずに、そのまま７年生に進級するという形になります。９年間の学びの場ということで、小学校に比べて、中学校は数字が少なくなるということをご理解いただければと思います。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"この数字だけ見てどう考えたらいいのかというので、ちょっと質問したいと思っているのです。そうであるとしたなら、この数字はどういうふうに見たらいいのかという問題意識でちょっと質問しているのです。","respondent":"有馬学務課長","answer":"例えば、ここは学区域が広いということで、もともと小学校との連携をどこでやっているかということもあります。例えば、ここはやはり荏原第六中学校へ行くといった傾向があるので、マイナスの数字が出てきているということで見ていただきたいと思います。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"この間ずっと経過を追っていった上での質問でないだけに、大変恐縮なのですけれども、もう少しその辺を見ていきたいと思っています。ちょっと気になるという感じで受けとめたので、もう少し過去の状況も見ながら、研究していかなければいけないと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それをお願いするのが１つと、空きスペースでみたいな感じではなくて、きちんと別に教室を用意していただきたいということがあります。カウンセリングをする部屋などに、どうしてもしわ寄せが行ってしまうので、その辺の環境をぜひ整備していただきたいと思っています。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"基本的に人口推計をしていまして、どうしても教室が必要だという学校が出たときに、どこを教室にしていくかということは内部でも検討を進めています。今後とも学校を見ながらいろいろ、ブースの仕切りを設けることでスペースを増やす工夫を支援してまいりたいと考えています。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"今お話があったように、教室をメディアセンターとして使わないというのは言葉が変ですけれども、別の方法でやることはできます。最後に１つだけ、それぞれ影響がないように、今お話にあったような形でぜひお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"山中小学校はいきいきという高齢者の方等も教室を共有している部分がありますけれども、今後どうなってしまうのでしょうか。現時点で山中小学校は２クラスで、３クラスにするとなると、教室が確保できるのか尋ねました。","respondent":"有馬学務課長、篠田学校計画担当課長","answer":"現状でいえば、もう来年度の予算に平成３１年度の教室を確保するための予算取りを準備しているところです。具体的に人口急増への対応ということで、今、学務課長から説明があったのですけれども、同じ人口急増への対応として１つ、学校の改築があります。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203794?Template=document&Id=4930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":16424,"voices":59}},{"id":"h29-20171129-5","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"総務委員会","time":"午後１０時１０分～午後 ４時１４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"「議案審査」を議題とします。 審査の都合上、初めに(5)第８２号議案 職員の給与に関する条例の一部を改正する条例","agenda":"「議案審査」を議題とします。 審査の都合上、初めに(5)第８２号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"特に、品川区議会議員および品川区長は、区民から選ばれた、区民の代表であるわけですから、この方たちは、我々も含めて、逆に下げるべき。意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いただいた資料の２の改正内容についてお伺いをします。４級が多分、６級以上が部長級以上だと思うのですが、この中身がどういうことなのかの説明を求めました。","respondent":"黒田人事課長","answer":"５級のいわゆる係長職のところにつきましては、平均で０.２％の引き上げで、６級以上の管理職員につきましては０.３％の引き上げを行ってあります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"４～５級が０.２％、６級が０.３％ということなのですけれども、上がり幅が増えていくというところなのです。ここ３年くらいこんな状況で、平等ではないという思いがあるのですが、その辺のご意見はいかがか尋ねました。","respondent":"黒田人事課長","answer":"ならないという要素ではないと思いますが、そういった意味でも、給与面でもそういった職責の高まりを反映した上で給与を改定したというのが今般の給与の改定内容です。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、若干、さっき意見を述べたように、アンバランス、不平等なところがあるので、その辺は改善していただきたいと思っています。全体的には賛成ということで意見を添えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"第８０号議案 品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例および(4)第８１号議案","agenda":"第８０号議案 品川区教育委員会教育長の給与および旅費ならびに勤務時間その他の勤務条件に関する条例の一部を改正する条例および(4)第８１号議案","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"改正の趣旨のところに、品川区特別職報酬等審議会の答申どおりということで、先ほど課長から、職員に準じた内容と説明をいただいたのですけれども、私は、一般職の方々と特別職の報酬というのは考え方が違うのではないかと思うのですがとの意見を述べました。","respondent":"米田総務課長","answer":"私どもの区では平成２６年４月１日に減額改定を行って以降、１８区でそれ以降、引き上げの改定を行っていると。総意といたしまして、０.１３％と期末手当の引き上げ率について、一般職の職員と同様に引き上げるべきであるという結論に達したものです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"一般職の方々の状況は、先ほど賛成をいたしましたように、引き上げるべきであると思っています。意見だけで終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"私は、そういうことを思えば、区議会議員とか区長は逆に下げるべきだと思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"質問を１点します。私、その歴史的経過というものの中身を教えていただけると判断がしやすいと思うのですが、いかがか尋ねました。","respondent":"米田総務課長","answer":"明記するということも１つでありますし、職責というものも同じ程度であろうというところでの条例のつくり込みで、かつてからこういう形でつくられているものと理解しています。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"ですから、しかるべきときにはきちんとした額をとって、きちんと重責を果たしていただくという考え方が妥当と思うのです。議員の額が妥当かどうかというよりも、この時期に値上げになってしまうということについては理解が得られないのではないかと判断をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"もう議員でなくていいとなったわけですから、これも改善して、一般の人がやるべきではないかと私は思います。教育委員も、今お話ししたとおり、同様に日当制という形で持っていくべきではないかと私は考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、今回は、今の制度にのっとった報酬の議論ということで理解して、賛否を言わせてほしいと求めました。その監査を受けたところできちんと活かすということを優先して、報酬のことはまた、その制度とは切り離して考えるべきではないかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"吉田委員","kind":"意見","question":"先ほど申しましたとおり、区長、副区長に関しては、給与および旅費ということに関しては賛成なのですけれども、これに賛成してしまうと、議員の期末手当も一緒に上がってしまうということで、そうしますと、主張の趣旨と整合性がとれないので、反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-03","title":"の２、「報告事項」を聴取いたします。 まず、(1)長期基本計画の検証状況","agenda":"の２、「報告事項」を聴取いたします。 まず、(1)長期基本計画の検証状況","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"そのスケジュールを教えてほしいと求めました。(3)のその他のところに区内団体等へのインタビュー実施とありますが、どのくらいの規模でやられるのか、そこのところの説明を求めました。","respondent":"柏原企画調整課長","answer":"どういった形での提供ができるかは検討したいと思いますが、基本的には、こういった議会報告の中でといったところが中心になってくると思います。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"今回、来街者の方のアンケートをとられたということで、興味深く見させていただいたのですが、ＷＥＢモニターがよくわからないので、選択の仕方とか、どうやって選ばれて、意見を集められたのか、その辺の説明を求めました。","respondent":"柏原企画調整課長","answer":"いろいろなアンケートに答えますというのを登録するというものがありまして、かなりの数、こういうアンケートをお願いしますと投げております。こういったアンケートは、最近よく使われていると聞いています。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"問８のところで、あと障害者の就労の場の機会を持ってほしいというのも、かなり１０年前と比べるとポイントが上がってきている。パブコメを最後にとるだけではなくて、ぜひ入れていただきたいと思うのですが、この点はいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"そういうのも含めて進めていきたいと、場合によっては、それを十分検討しながらということで考えていきたいと思っています。今回はなるべく多くの方にアンケートを実施したかったというところもありますし、これからもいろいろ検討しながら。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４次の総合実施計画の中で数値なども具体的にしていきたいとおっしゃっていたので、どこがかなっていて、充実していってほしいと求めました。その点はいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それから、職員がきちんとノウハウだったり、そういったものを継承できるかというのは、両方あわせながら検討すべきと思います。どちらがよくて、どちらが悪いということではないと思いますので、トータルの考えの中で進めていきたいと思ってあります。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"第１回検討委員会のことが冒頭のＡ４の資料で、ここに内容で３点ありまして、審議なりをしたのかということを伺いたいと思います。それとほかの回答についてのクロス集計みたいなのがされたのかどうかということも伺いたいと思いますので、それだけの説明を求めました。","respondent":"柏原企画調整課長","answer":"ご報告する際も、どういった形でお見せできるかというのは、今後検討したいと考えています。回答していただいたのは、このアンケートに回答者属性という項目がありますが、４６.３％ということでの男女比になります。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうここから読み取るか。その辺のクロス集計はしながら活かしていかないと、読み誤ることもあると思いますので、その辺はぜひご検討いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうもので、みんなさまざまな意見をぶつけてくるわけですから、それをどうやってまとめるのか。８ページのところで、問２の１番目、考え方が全く違うではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"「重視してほしい施策」の中で、生涯学習・スポーツ活動の質問で、「生涯スポーツ施設の整備」が１位になっているではないですか。委託されているのかどうかも含めての説明を求めました。","respondent":"柏原企画調整課長","answer":"検討委員会でも同様なお話が出ておりまして、それはぜひ、積極的にやっていきたいと思っています。もともと１０年前のアンケートがあったので、職員が手を入れながら、最終的には委託しているコンサル会社と相談してつくり上げた内容のものです。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"活かしてほしいと求めましたが、いろいろなときに、いろいろな手法でとられていると思うのです。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問","question":"質問していたのですけれども、１つ、私がずっと感じていることがこういうところで出てきたというところで非常に興味深く感じました。そういう項目、今回のアンケート結果から、そこを見直すということをここでおっしゃっているのかについて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"今後検討を進めていく中では、今、副委員長がおっしゃったような内容は検討の１つの大きな論点、視点になってくるだろうと思ってあります。検討していきたいというのがありますので、直接、そういったことも含めて検討をしたいという思いです。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"俎上にのるということを確認させていただきました。そのようなことで、これをもう一回、確認をさせていただきたいのですが、この長期基本計画に関してです。","respondent":"柏原企画調整課長","answer":"考え方といたしましては、区が主体となった考え方で進めるというのが、まず第一なのだろうと思います。そういったところも含めて、そういう考え方も視野に入れながら、品川区の計画ということでつくり上げたいという思いです。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"４ページ、「まちづくりに関する取り組みの中で重視すべき取り組みはどれですか」というところなのですけれども、やはり１０年前と同じように。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-04","title":"地方公会計制度に基づく財務４表","agenda":"地方公会計制度に基づく財務４表","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"その移行期というのでしょうか。どういうふうに変わっていくのか、ご説明いただけると助かります。","respondent":"秋山財政課長","answer":"そこの公会計について検討していますということは載せますけれども、具体的にどうなるかは、そこまではできていません。実際に日々仕訳でどうなっていく、新公会計制度のＰＲといいますか、そういうご報告の中で変わっていきますという形で周知をする形になると思います。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"「平成２７年１月に『統一的な基準による地方公会計の整備促進』を要請されました」ということで、もう一回、はっきりお伺いしたい。あちこち違った方式でやるのか尋ねました。","respondent":"秋山財政課長","answer":"より企業会計に近いのが東京都で、東京都方式のほうが採用する団体が少ないのですけれども、２３区中の８区が東京都方式を採用する形になります。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"変換はできるのかもしれないけれども、そうやって違うものを各自治体で使うのか、それは自主性というところなのですか。そうやって１つのものに連結されていって、議論ができることになるということなのかどうか、そこのところの説明を求めました。","respondent":"秋山財政課長","answer":"国との検討の中でも、それは１つにまとめることはできない、２つの方式を認めているものです。私どもも、東京都方式でやりますけれども、総務省方式に変換もできるということで、特に複雑になるとは考えてございません。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"連結財務４表については、具体的にどういうところで取り上げられる、議論ができるのですか。質問したいとか、疑問があるというときに、どういうところでその中身の議論をさせてくれるのかどうかというところはどうか尋ねました。","respondent":"秋山財政課長","answer":"今でも、品川区国際友好協会であるとか品川区文化振興事業団につきましては、報告として、各団体の事業報告と決算報告等が出ておりますので、その中でご議論いただくことになっております。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"去年の１月から個人番号カードが希望者には交付をされているわけですけれども、届いていない人がいらっしゃるのかどうか。そこのところの説明を求めました。","respondent":"仁平情報推進課長","answer":"基本方針に挙げております各事務の照会方法なのですけれども、こちらを職員が操作する形で、特定個人情報の照会と提供を受けるという仕組みです。直接、このカードは、情報提供に関しては関係ない仕組みになっております。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"個人番号カードの発行率が人口比で１３％と、大変厳しい数字だと思うのですが、今後、この辺はどうしていくのか伺いたいと思います。マイナンバー制度をやめてほしいと事あるごとに言っているのですが、区としてどう考えているのか、大もとのところを説明するよう求めました。","respondent":"仁平情報推進課長","answer":"そういうことを考えますと、コンビニ交付が累計で１万５,０００ぐらいにはなっていますので、そういうのがとれるような形のサービスもあります。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、１３％にとどまっている個人番号カードを請求される方を増やしていくようなことをこれからやられるのでしょうか。いかがか尋ねました。","respondent":"仁平情報推進課長","answer":"方針（案）にあります委託事業者の関係です。職員等の研修を行いながら、ガイドラインにも示されておりますし、区の取組みも同様の扱いをしているものです。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当にしっかりと今の段階ではやっていただきたいと考えていますけれども、何としてでも国の段階で廃止をしてほしいと期待をしているところです。ここは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"資料の１７ページの６番の品川区における特定個人情報保護評価対応についてという中身が私はよく理解できないので、教えてほしいと求めました。その辺の説明を求めました。","respondent":"中元広報広聴課長、仁平情報推進課長","answer":"こちらは１８ページからありますが、情報公開等審議会というのが常設ですが、そちらで第三者点検を実施させていただいたものです。２につきましては、広報広聴課長の説明があったとおりでございまして、重点と基礎という評価書の分かれ方になります。この制度を区が開始する前に全て終わっておりまして、問題があれば、個人情報保護委員会から指摘を受けます。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"今、ここで説明するのは、すごく大変なことでしょうか。もし、すごい大変だったら、後で個人的に伺いますけれども、もし、ざっと説明していただければ、伺いたいのですが。","respondent":"仁平情報推進課長","answer":"方針（案）の３０ページの下の囲みの中に、今の特定個人情報保護評価の評価の内容とか実施等を説明しています。ちょっと話が難しい形になりますので、もし、それ以上のご質問があれば、またの機会にご説明させていただきたいと思います。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりまた改めて個別に伺いたいと思いますが、今、新たな個人情報のような使われ方をするのではないかという危険性のところで反対をしております。第２次対応ということで、万全は期していただきたいのですけれども、情報に関してきちんとしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-05","title":"防災行政無線設備更新工事請負契約","agenda":"防災行政無線設備更新工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この防災行政無線設備更新工事というのは、今年の初めのプレス発表のところに載っているデジタル化と関係があるのでしょうか。そこの中身をざっくりの説明を求めました。","respondent":"立川経理課長","answer":"少しだけ説明します。全て終わるのに平成３３年までかかるということを聞いています。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"実際に、平成３３年までに順次、かえていって、老朽化はもちろんあると思うのですが、具体的にどこがどう改善されるのか。そういうところの改善も今回の中に含まれているのかどうかの説明を求めました。","respondent":"立川経理課長","answer":"中身につきましては、所管で。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり内容を伝えていただきたいし、必要な工事だとはわかっていますが、この金額が妥当かどうか判断する大もとの問題だと思うのです。具体的な中身を聞きますけれども、いつものように、辞退の理由の説明を求めました。","respondent":"立川経理課長","answer":"今回、７業者ございまして、２者は積算額が予定価格を超えたものです。もう１者が自社都合によるです。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"結局、７者がトライをしたけれども、２者の入札金額で低いほうが選ばれたということなのですけれども、この工事自体が難しい工事なのか、新しいことを取り入れた工事なのか、大体、ここに挙がっているような企業だったらやっていける中身なのか。","respondent":"立川経理課長","answer":"この工事につきましては、対象業種としまして、電話通信、そういった専門性のある事業者に限るということで報告を受けておりまして、東京都全体と品川区で工事をする意思のある、そういった登録のある事業者が自主的に、とりあえず申し込みを行ったというのがこの７者です。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"１回目の入札の金額の違いがあるのですけれども、一つ一つ、積算の項目の比較をするのでしょうか。赤本の中身でどう積算するのかというのがわからないので、この２者をきちんと比較して、その辺を説明するよう求めました。","respondent":"立川経理課長","answer":"既に申し込みを行った事業者については、防災行政無線の設置については問題ない、そういった判断でやっているところです。これはあくまで競争ですので。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"そういった判断が１つあるということは、新しい事業者が参入するときは、すごい不利になるのでしょうか。そこだけ、最後に説明するよう求めました。","respondent":"立川経理課長","answer":"格付というのは、企業の経営状態でありますとか、過去の受注実績とか、そういったもので異なってきます。過去１０年間で官公庁の発注の類似工事の実績が予定価格の５０％以上あるということになりますので、実績のない事業者については参入ができないです。","id":"exchange-041"},{"speaker":"石田（し）委員","kind":"意見","question":"基本的には平成３４年までにやる残りの工事も同じ内容になるのか、年度によって、契約の内容によって変わってしまうのか。そこだけ知りたいとの意見を述べました。","respondent":"立川経理課長","answer":"防災課から聞いたのですけれども、どういったシステムを入れるかというのは、事前にプロポーザル方式で選定するですので、今後導入する機械につきましても、今回導入するシステムと同一のものということで聞いています。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、少なくても、こういう更新工事、入札になりましたという話ぐらいはしてほしいと思うのです。それについてだけ、意見の説明を求めました。","respondent":"立川経理課長、伊藤委員長","answer":"どこまで深く話せるかというのはありますが、基本的なことにつきましては、ご報告申し上げたと考えております。例えば建設委員会の資料、ぜひ、そういうのを見ていただいてから質問していただきたいと思います。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問・要望","question":"何も突っ込もうというのではなくて、こういう内容で、こうなりましたということぐらいは話していいのではないかと思うのです。やはりそういう話や情報は提供していただきたいという意見だけであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あくつ副委員長","kind":"確認","question":"この場で全部というのは難しい話ですから、必要な情報がわかるわけですから、それは所管の課長に聞いて委員会に臨むのが我々の仕事だと思っています。わかれば、そこだけ確認したいと求めました。","respondent":"立川経理課長","answer":"そこについては、所管に確認します。","id":"exchange-045"}]},{"id":"topic-06","title":"住民税（普通徴収）・軽自動車税のクレジットカード等による収納開始","agenda":"住民税（普通徴収）・軽自動車税のクレジットカード等による収納開始","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今回、１８歳の選挙権で、いろいろ工夫次第で投票率は上がるのだという希望が持てると思っているのです。いい方向に持っていっていただきたいのですけれども、考えていらっしゃることが何かあったら、の説明を求めました。","respondent":"安井選挙管理委員会事務局長","answer":"１８歳のほうの啓発は、メッセージカード等をやっていますけれども、１９歳のほうも何らかの対応を考えていかなければいけないと思っています。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762881?Template=document&Id=2096#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":58623,"voices":166}},{"id":"h29-20171129-10","meetingId":"h29-cm11","date":"2017年11月29日","dateIso":"2017-11-29","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員","kind":"意見","question":"１点、委員会運営上、一定の発言をする際はまとめて内容を発言していただければなと思います。ぜひその点は皆さん少し考えていただいて発言をされたほうが委員会運営上いいのかと思いますので、ぜひお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"今の発言の趣旨がよくわからなかったので、具体的に例えばどんなケースが、実際にあったのだったらの説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば１つの議題に対して各議員が質問をされますね。例えば行ってこいで何回も同じようなことを繰り返し質問して答弁が、何回も繰り返されるような発言はぜひ考えていただきたいなということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5256#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1496,"voices":12}},{"id":"h29-20171130-14","meetingId":"h29-cm11","date":"2017年11月30日","dateIso":"2017-11-30","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"１３号の請願の文面、もしそうだとすればこちらは事実と異なりますし、前提が違ってしまう。そういう意味で、区ではどのように、このブラインドサッカーへの影響を捉えられているのかの説明を求めました。","respondent":"中村都市計画課長","answer":"関係機関と連携する中において情報収集もしておりますけれども、そういう事実は、委員ご指摘のとおりございません。東京都、こういった実際にオリンピック・パラリンピックを運営する側の機関の中で、そういった情報や発言はないという確認をしています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国際ホッケー連盟が旅客機騒音を懸念して、要は競技に対しての騒音を懸念して調査対策を求めているとあります。これが行われているのか、どのように調査し、どのような対策が出されたのか、出されるのか、その辺がわかっていれば伺いたいと思います。","respondent":"中村都市計画課長","answer":"この会場の変更につきましてはさまざまな検討が行われたと聞いております。ただ、これは今回の新ルートによる騒音に特定した、そういった調査とは聞いておりません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どういう対策が検討されているのかとお聞きしましたけれども、今、航空機騒音によるものではないというような説明だったですかね。そして、こうした報道なども知り、区としてはどういった見解をお持ちか尋ねました。","respondent":"中村都市計画課長","answer":"ただ、この会場を選定するための環境を検討する場合に、あるいは航空機も上空を飛ぶ場合にはそれも検討の要素には入るかと思います。こういった空港の、航空機だけに特定されるものではなく、さまざまな条件を総合的に踏まえて検討がなされるものだというふうに考えてあります。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"騒音が８０デシベルを超えるわけですから、人と人が話すにも耳元で話さないと聞こえないレベルですよね。こうした運動公園でもルート直下ですので、どのような影響があるのか、あると考えているのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"ただこの変更になったことで既にもう羽田空港の影響があるのかないか、こういった検討はもうそれ以上なされる必要もないと考えております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"影響がないと判断されたとおっしゃっていますけれども、区としても影響はない、全くないと、今まで以上の影響はないとお考えなのでしょうか。こういったルート直下にある運動公園で影響がないと考えられているということか尋ねました。","respondent":"中村都市計画課長","answer":"競技場の環境が厳しくなったり、あるいは許容されたりと、そういった条件があるということはやむを得ないことだと思います。他の都市、やはり他の自治体も空港の騒音によって特に公園の利用の制限があるということはないという、そういった情報もいただいております。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"騒音がある中でどういう支障が出ますかと、８０デシベルというのを想定してお聞きしましたら、感じるのではないかと言っていました。そこを少しお答えほしいと求めました。","respondent":"中村都市計画課長","answer":"国の、今あくまで案という中で、この飛行経路に対応するもの全てを今から準備するというのはなかなか難しい、実際には難しい話です。そういったことで必要な対応を国へ求めていかなければいけないと考えています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"南風のとき、午後３時から７時の間、この品川上空を最大４４機も２ルートで３００メートル以下で通ると計画が出されているわけですから。ぜひ、答えるよう求めました。","respondent":"中村都市計画課長","answer":"どういうものがあるかというのは非常に推測は難しいものだと考えますけれども、人と人が一定程度ぶつかり合ってボールを奪い合うゲームです。区民の皆様からいろいろな声をいただくでしょうから、これをしっかり国に伝えて、必要な対応は求めていく必要があると考えています。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう中で影響がない、もう飛んでしまったら騒音も防げないというのが今回の計画なので、影響をはっきり言えないというのはなぜなのでしょうか。想定できる影響をもう一度伺いたいのですけれども。","respondent":"中村都市計画課長","answer":"そういったものをとり除いて純粋に８０デシベルという音だけを考えただけでも、これは本当に難しい話だと思います。ただ、区民の皆様がきちんと健全にけがなく競技を、スポーツを楽しんでいただけるように注視はしてまいりたいと考えております。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして教室型の説明会を求める請願も賛成少数で不採択になってしまいました。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、そこについてはぜひこの委員会で、記事も読んでいない方もいらっしゃるでしょうから確認をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"済みません。影響というのが何かしら、もし何かあるのであれば教えていただきたいと思うのですが、いかがか尋ねました。","respondent":"小林環境課長","answer":"公園が外部から受ける音に関しましては、これについては特に建物とか学校とか、そういったところに対しての基準です。しかし、屋外の運動公園という観点では、そういった判断基準はないというものです。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"騒音がちょっとうるさいということから、何か行政的に対応、騒音を防止するような事例をつかんでいるものがあれば教えてほしいと求めました。教えてほしいと求めました。","respondent":"小林環境課長","answer":"伊丹空港、福岡空港ともに、特に大きな規制等はかけていないとのことです。近接する大田区につきましても、確認をしたところ特に大きな規制はかけていないとのことです。","id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"皆さんが同じく納得とか理解のできる形での影響というものを示すというのがなかなか難しいであろうということは、今の答弁から得たところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"請願第１３号ですけれども、それと同様にこういう影響もあると気づかされるものだと私は思いました。例えば伺いたいのは、周知がされているのか、どのようにされているのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"今、国のほうではこの案を示した中で、必要な対応について説明会を開催して周知を図っていく段階です。その中で品川区内、あるいは品川区だけではなくて、現在のところはオープンハウス形式による説明会で周知をしております。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり丁寧な説明を求めるというのは、どのような立場であろうが丁寧な説明を求める、具体的な説明を求めるという意見書を提出した区議会としても。態度表明のときでもいいのですが、もし何かあればぜひお考えを聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、まるで私がこの内容に何かそこを突ついたような、悪印象をつけるような発言はやめていただきたい。これは申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"丁寧に、具体的な説明を求めるという内容なので、これは採択すべきですし、意見書の内容そのものなのですよね。態度表明だけでもいいのですが、もし何かあればぜひ皆さんのお考えを聞かせていただきたいというのを伺ったのと、そちらの見通しをお伺いします。","respondent":"中村都市計画課長","answer":"今区内に広く広報によって説明会等のお知らせをしたり、あるいは町会へは回覧板や説明会のお知らせをしたり、その中でこういった協会。そういった中で説明会に参加していただいて、必要な情報を得ていただきたいというふうに考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですけれども、状況があまりに違うのではないかということなのですけれども、認識をお聞かせください。２つ目は、これほどの資産価値の下落の影響というのは、これは重大な損失だと思うのですけれども、この影響をどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"この国から示された案に対して、品川区では国に対して必要な情報と丁寧な説明を求めているところです。そのような中で、国にそれを問い合わせたところ、国のほうではこの資産の価値について直接的な因果関係は認められなかったという説明でございました。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"その中で今回の羽田新ルートとは状況が違うのではないですか、違いますよねということを伺ったので、その影響についてお伺いしたいということです。","respondent":"中村都市計画課長","answer":"ルートは意図的にこうしたということではなくて、検討の結果そうなったという、結論ありきではなくて検討した上での結論と認識しております。国では過去にそういった空港の事例をもとに試算した結果ということで説明があったものというふうに認識しておりますので。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"それで、請願第１４号の内容について少しお伺いします。なぜ４３年前の区の判断が変わったのかと書いていますけれども、なぜなのかお伺いします。","respondent":"中村都市計画課長","answer":"今回の新ルート案につきましては、もうさまざまなシミュレーションを行った結果、選択肢がもうこれしかないということで国から説明があったものです。以前区と国と、これも航空機の性能が国の説明では上がって、改めて今回この案を提案するものであるという説明でありました。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"ですから今回も反対表明し、新たな選択肢を切り開いてほしいと思いますけれどもいかがでしょうか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"滑走路の処理能力を再検証、つまり最適化することによって国の説明では年間１.３万回増便できるとしています。ただ、合わせて国の説明の資料の中では、滑走路の飛行経路を見直すことによってさらに２.６万回アップしなければ対応できないという説明です。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"私がここで伺いたいのは、区長が国交省に行って大臣に会ったのはいつなのか、何を話したのか、羽田の問題で会いに行ったのでしょうか、伺いたい。そして事務次官と審議官に会ったのはいつでしょうか、何を話したのか伺いたいと思います。","respondent":"中村都市計画課長、鈴木（ひ）委員長","answer":"申しわけございません。事務次官や審議官に会ったというのもいつなのか、何を話したのかについてもお答えをお願いします。事務次官、審議官と会見をしまして、そのことをしっかりと伝えたところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"それも教えてもらいたいですけれども、大臣に会った日と事務次官と審議官に会った日とは別なのか、そして大体それぞれいつごろなのか。","respondent":"中村都市計画課長","answer":"これ以上のことは申し上げることはできませんが、品川区に対する配慮事項としてさまざま示されておりますけれども、そういったものがしっかり実行されるようにという内容であったと記憶しております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"何か隠さなければいけない事情でもあるのですか。お伺いします。","respondent":"中村都市計画課長","answer":"これは事務次官、審議官、別々の日だったというところです。内容については先ほど述べたとおりです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"ですから全然違うのですけれども、区長が言っていることと、今の区を代表して言っている課長の答弁とどちらが本当なのですか。区長はあの場では違うことを、うそを言ってしまったということなのか尋ねました。","respondent":"中村都市計画課長","answer":"これは当然デメリットしかないところで、可能な限り少なくするように、こういったことを求めるのは当然なことであるというふうに考えております。メリットにつきましては、これは品川区に対する配慮事項の中で、いろいろと地域に対しての支援等がございましたけれども。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"区長が言う、品川区民にとってのメリットというのは何なのでしょうか。命にまさるメリットなどないと思うのですが、区長が言うメリットとは何か尋ねました。","respondent":"中村都市計画課長","answer":"タウンミーティングでも区長が申し上げたとおり、詳しい過程は申し上げられない、まだ決定していないことについて交渉の過程をオープンにすることは、交渉の相手方にとってもフェアでないと考えた結果だと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"そのことを本会議でも伺うと、いや、区としては容認したわけではないという答弁でした。どうしてこのような条件闘争の交渉をしたのに、区としては容認したわけではないと言えるのかお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"国際競争に勝っていかなければいけない日本の立場として、この空港機能を強化する必要があるということは理解をしたです。これは国際競争の中で日本が勝っていく、これについての考えとは別問題として、この案についての懸念を申し上げたものです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"これはどう見ても容認していると見られても不思議ではないと思うのですが、そういうことを続けるのですか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"品川区上空を飛行することについて、これを理解したり承認したという事実はございません。ですので、あくまで空港の機能強化です。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"やるべきなのは反対表明、反対表明しないのは国策だからなのでしょうか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"現在は反対・賛成というところではなく、やはりまずは必要な情報を得ることから始めなければいけないと考えております。仮に飛行経路が実現された場合の交渉としてそういったものが考えられるということで、そういった決定や承認が前提というものではございません。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"でも伺いたいのは、あえて区長は自らが反対表明をしては大変だと、国の政策に大変な支障を与えてしまうからということで反対しないのですか。どうか尋ねました。","respondent":"中村都市計画課長","answer":"そういった中で、また８０デシベルというのも大井町駅上空で１つの例示として示されましたけれども、まだ国から出されていないところです。丁寧な説明も求めていくという考えに変わりはなく、引き続きそういったところを行っていきたいと考えております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、それは反対するということの重さというのを区長自身が認識しているからということなのですかと伺ったので、しっかりとお答えほしいと求めました。","respondent":"中村都市計画課長","answer":"今現在、区民の皆様にしっかりと丁寧に出して説明もしてくださいという以外には、今のところございません。申しわけございませんが、ご理解をお願いいたします。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう区政をつくっていかなければいけないと強く思いますし、そのように今からでも変わっていただきたい、反対表明をしていただきたいと繰り返し強く申し上げまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"しかしどこで下げられるかはわからないということだったのですけれども、このことを区は把握はされていたでしょうか。伺います。","respondent":"中村都市計画課長","answer":"この脚下げのタイミングについても、区民の皆様からもそういった質問をいただいて国へ問い合わせても、国からはやはり今委員がおっしゃられたとおり、同じ回答でございました。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"でもやはり安全を守るためにはこのような計画はやめるべきだということをぜひ言ってほしいと求めましたけれども、区の見解はいかがでしょうか。この危険に対して。","respondent":"中村都市計画課長","answer":"これと今までの説明会を合わせますと累計で約３,７００名がこの説明会に参加されたことになります。そういったところで引き続き、教室型説明会を求めてまいりたいというふうに考えてあります。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、安全を求めているのに、私たちがそのことを聞いても、安全は絶対ではないのですと言うのですね。こういう計画で何で飛ばすのですかと、安全は確保されないともうわかっている計画は、すぐにでも反対表明してやめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"渡部委員","kind":"質問","question":"多くの方々、飛行機が飛べばどういうふうになるというのもおおむねわかっていらっしゃるのかなというように、私どもは考えてあります。以上の理由から、本請願については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"したがいまして、説明会についても多様な工夫をしっかりとまた引き続き国には要望もしておりますし、意見書も出しております。その意見書の趣旨を十分にくみ取って、国は引き続き努力を尽くしてもらいたいという立場から、不採択で結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"この内容ですけれども、区が国に説明を求めるということで意見書でもありますような具体的で丁寧な説明を求めているという。これを採択することで意見書のさらなる推進と言うのですか、私はこれは採択して当然だと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"ていねいな説明をしてくださいということも当然求めているというお話でした。総意として意見書が出され、区民に説明を求めるということはこれからもしっかりとしていっていただきたいというのも私たちも思うところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"落下物、当然航空事業者また国土交通省にゼロを求めて言っていくのは品川区として言い続けていかなければなりません。以上、意見を述べてまいりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"若林委員","kind":"意見","question":"第１４号の請願は、継続という判断をいたします。引き続き議論の余地があるでしょうということで、継続をずっと主張しておりましたので、同じ扱いとしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"安藤委員","kind":"意見","question":"住民の命と財産をおびやかすということになると思いますが、それを避けるためにはやはり現在の海上ルートを堅持していくということが重要です。品川区としてやらなければいけない、できることだと思いますので、これは採択をすべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"大倉委員","kind":"質問・要望","question":"ここ数年、この問題についてもいろいろ議論をさせていただいておりましたし、会派としてもいろいろ調査をしているところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"若林委員","kind":"質問・要望","question":"私どももそういう意味では意見書を出したということも含めて、賛成、反対という今、現段階では立場ではありません。議会から品川区に対して見直すように国に要望してくださいと、こういうことについては要望は、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-02","title":"平成２９年請願第２１号、林試の森公園隣の国有地に、特養ホームや老健施設、障害者施設などの建設を求める請願","agenda":"平成２９年請願第２１号、林試の森公園隣の国有地に、特養ホームや老健施設、障害者施設などの建設を求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"私は５,０００平米と言わずもっと広げられるのか、５,０００平米以上とれるようになるということは、あまり可能性はないのでしょうか。そこを伺いたいです。","respondent":"柏原企画調整課長","answer":"もろもろの行政需要に対応ということで、交渉といいますか協議等の上では５,０００平米ということで、こちらも提示して交渉している状況ですので、何とか５,０００平米はとりたいということで努力はしていきたいです。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"全体で２１％ぐらいでしたか、やはり特養ホームの必要性もこれは高くなってくるのではないかなというところで区の見解を伺いたいと思います。高齢者の特養ホームや老健施設、そして障害者施設のこうした区民の実態にも照らした区の見解を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"先ほど申し上げましたように、ボリューム的なところ、詳細のところに検討がなかなか入りづらいというところがあります。ですので、繰り返しになりますけれども、さまざまなものに対応するために取得に向けて努力をしていきたいという姿勢でいるというものです。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"考えられているのでしょうかということと、早くても平成３１年度ということだったのですけれども、そこからの計画ということになるのですよね。そこの確認を、済みません。","respondent":"柏原企画調整課長","answer":"こちらにつきましてはエリアと言いますか、現段階でこれとこの施設がというのを確定的なところで検討することがなかなか難しいという現況があるです。取得が決まってから検討ということではありませんで、繰り返しになりますけれども、その検討には入るというものです。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"２万６,０００平米あるわけですから、最初に５,０００平米を提示して交渉するとおっしゃいましたけれども、いかがでしょうかというのが１点です。","respondent":"柏原企画調整課長、中山障害者福祉課長","answer":"こちらは公になって、国のほうで処分するという方針が出ましたので、この土地ということでずっと交渉していたです。特に例えば自力で通所される就労継続Ｂ型であるとか、こういったものがこの地域にもう少し整備されるべきだというふうには思っております。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"５００人に迫る感じの方が応募していて、１００歳でも入れないという大変な状況はやはりあるという中で、所管のお考えを伺いたいというのが１つです。５,０００平米と言わず、交渉していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大串福祉計画課長、柏原企画調整課長","answer":"ショートステイ９床を含む９０床、９０名定員の特養ということで、平成３１年の開設をめどに今法人で整備を進められているといったところです。東京都の考え方としては１以上ということで、区の中にある敷地だというところで、一定程度の広さが欲しいという交渉をしているという状況です。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"特養ホームのほうはよくわからないのですけれども、やはり現状からは増やさなければいけないという認識はお持ちということでよろしいのでしょうか。それだけお伺いします。","respondent":"大串福祉計画課長","answer":"先ほどご答弁申し上げましたように、総合的に判断をするということです。合わせてソフトの支援、こういったものも２つ、両輪合わせながら高齢者福祉は充実させていきたいと考えているところです。","id":"exchange-050"},{"speaker":"安藤委員","kind":"意見","question":"そしてこの環境ですけれども、非常に公園の隣ということもあって高齢者の方にとっても障害をお持ちの方にとっても非常にいい環境だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問・要望","question":"５,０００平米しっかりとれるものなのか、この地域においては小山台二丁目町会が孤立することがないようにという、一番大きな課題があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"若林委員","kind":"質問","question":"で、総合的に判断をしていただくということがこれはもう当然のことだと思いますので、これを採択するということにはならないと思います。そういう理由です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりどれもが区民の皆さんの非常に切実な願いで、請願者の方はそれを代弁しているわけですけれども、足りていないということですよね。むしろ今の現状で偏っているバランスを少しでも正常な方向に行くと私は思うので、これはぜひ採択してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"大倉委員","kind":"質問","question":"本日結論を出すということで、態度は不採択ということでお願いします。そういうような総合的な判断をしっかりとしていただけるようにという部分が思いとしてありますので、態度は不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-03","title":"本日は、基礎自治体のあり方に関することを議題といたしまして、品川区の人口動向","agenda":"本日は、基礎自治体のあり方に関することを議題といたしまして、品川区の人口動向","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"１８歳から２０代、３０代、４０代が増えているというところ。男女別がわかるのかどうかというところと、もし何か分析できるものがあれば、もしくは推測できるものがあればの説明を求めました。","respondent":"柏原企画調整課長","answer":"東京都内、特に２３区内で仕事をするというときに、ちょうどいい距離にあるとうのが言えるのではないかと思います。失礼しました。この段階では細かい数字は出ていないのですけれども、若い世代はほぼ同じような人数だったと思いますが、細かくは改めて調べたいと思います。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問","question":"なぜそれを伺ったかといいますと、なぜ消滅するのかというところの分析で、豊島区ではしているということでした。１つ伺いたいのが、前にも確か伺って、調べることというのは可能なのか尋ねました。","respondent":"柏原企画調整課長","answer":"以前もそういう議論があったというところで、私も承知していますけれども、所得とそれから転入・転出の関係の部分です。一定程度そこの分析というのは、論点の１つだろうというふうに思ってありますので、何らかの形で分析をかけたいというふうには思ってあります。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"意見","question":"１つ間違えると、そういう状況が今２３区の中でも起きているということは認識をしなければいけないのと、それがもうじかに起きているとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"それと、この算出のされ方を伺いたいのですが、多くの子どもを産んだ女性が区内にどれだけ存在するかということなのでしょうか。極端な話、そういう女性が区内に来れば上がるということなのか、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"考え方として、そういう方々がたくさんいらっしゃるということは、この合計特殊出生率は上がるということになります。だから実際産んだという人数をカウントして計算を積み上げていく考え方ですので、この合計特殊出生率も増えるという考え方になります。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"３人以上世帯の増加に関してはファミリー層の流入ということで、そういったことがやはり大きいということなのかというのをお伺いしたいのと。あわせてお伺いします。","respondent":"柏原企画調整課長","answer":"やはりファミリー世帯の住宅の事情ということで、そういう方々が流入されているというのは、１つ大きいのではないかというふうに思ってあります。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺ったのは、お答えいただきたいというのが１点と、これは目指していくというお考えもあるのでしょうか。伺います。","respondent":"柏原企画調整課長","answer":"平成３１年にはそこを達成したいということで、現在もそこの目標値に向けて、施策を進めたいというふうに思っております。当初設定したときは、我々も思った以上に伸びが出ておりますので、やはりこういった施策は進めていくべきだろうというふうに思ってあります。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"２.０を目指さないのかなというのはどうなのかということで伺わせていただきたいのと、そうは言っても。そして、その数を実現するために取り組んでほしい点というのが出ているのですけれども、あわせての説明を求めました。","respondent":"柏原企画調整課長","answer":"この特に出生の関係のところは、基本目標の１番目に掲げて、もろもろ施策を掲げさせていただいてあります。そういう取り組みをしているというものです。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"その答えが返ってきているわけですから、第１位が「保育施設など子育て施設の施策が充実する」第２番目として、どのような計画があるのか。これ充実していく必要があると思うのですが、区のお考えの説明を求めました。","respondent":"柏原企画調整課長","answer":"どういった形で品川区を子育てしやすい、住みやすいまちにしていくのか、品川区に来ていただけるのかという思いで施策に取り組んでいるです。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの不安にも応えたような経済的負担が重いということに対する新たな支援策というのですか、それがなくても１.４５まで行くという見通しなのか。そこら辺をお伺いしたいのですが。","respondent":"柏原企画調整課長","answer":"実施計画等もありますので、進めていきたいですので、そういう判断ではないということです。そういったお声にどうやって対応していくか、トータルで見ながらこの数値が上がっていくように努力をしていきたいというものです。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそこは今の現状での区の見通しというのを伺いしたいというのと、その後に住み続けられなくなっては意味がないと思っているのです。そこをお伺いします。","respondent":"柏原企画調整課長","answer":"１.４５を目標にして、これを目指すということで、施策の充実を図っていきたいというものです。１つの指標であって、１つ大きな施策の柱であろうというふうには思ってありますので、さらに図っていくというものです。","id":"exchange-065"},{"speaker":"渡部委員","kind":"質問","question":"やはり大きな政策が１本必要な中で、いわゆる地方行政も巻き込んだ上での話し合いというのは、される機会というのは実際あるのでしょうか。その辺１つどうか尋ねました。","respondent":"柏原企画調整課長","answer":"なかなかそこに地方の一自治体が手を挙げて機会として入っていくのはなかなか難しい面はあります。これは２３区全体で、そういった中でも、声は終始上げていきたいというふうに思っています。","id":"exchange-066"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう経験がなくなっているわけですから、当然１つ１つの施策をやっていくのも、その辺は私たちも研究を重ねていきたいと思います。単純にそういうふうに考えてしまうのですが、どういう分析をされているか、お伺いします。","respondent":"柏原企画調整課長","answer":"特に港区、いわゆる開発余地のある土地といいますか、場所がまだあるということは１つあるのだろうなというふうに思ってあります。ただ、そこは１つ２３区内で調査することで、そういったところは今後ちょっと分析を深くしていきたいというふうには思ってあります。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"平成３８年でしょうか、そこで子どもの数が頭打ちになってというところで、高齢化率はこれから上がっていくというところ。やはり総合計画、実施計画等にも練り込んでいただいて、やってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問・要望","question":"転入・転出のところで伺いたいのですけれども、２人世帯、その原因というのがもしわかりましたら教えていただきたいなというふうに思っております。お願いいたします。","respondent":"柏原企画調整課長","answer":"冒頭のところで、この資料の説明をした際にそういった特徴があるというお話をさせていただいたところで、６０歳代が減っているところについては。","id":"exchange-069"},{"speaker":"松永委員","kind":"意見","question":"今後、私も想像でしかないのですが、他区に行かれるケースというのはあまり考えられないかなと思います。住みやすいところに行きたいとか、そういうところも踏まえて、今後こういった動向を見据えながら取り組んでいただければというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう一度伺いたいのですが、この１人目は、数というか出生率の中には入らないということなのか尋ねました。","respondent":"柏原企画調整課長","answer":"考え方としては、そういうことになります。それが平成２８年は大田区で１人目がカウントされて、平成２９年は品川で２人目をカウントするという、構造的にはそういう考え方です。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"それとともに最後には目指すべき方向性の実現に向けてということで、人口減少社会を克服していこうというビジョンなんだなというふうに思うのです。","respondent":"柏原企画調整課長","answer":"政策として効果があって、区民の方に住み続けてもらえるのか。このことについて何もしないということではありませんし、こういったところとも協力しながら、我々も政策の充実に向けて努力していくというものです。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に進めていってほしいと求めましたし、やはり国に言うべきことは、国に言うべきことは言っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"大倉委員","kind":"質問・要望","question":"伺いたいのが、１人で仕事の都合で入ってきている人もかなり多いのかなというところで、こういった取り組みというのも１個必要なのかなと思います。","respondent":"柏原企画調整課長","answer":"後で郵送で送ってくださいとか、何してくださいとやり方をいろいろ当時も考えたのですが、なかなか実現には至っていません。それによって何を生み出すのかというところを考えながら、その手法等については、もう少し研究をさせていただきたいというふうに思ってあります。","id":"exchange-074"},{"speaker":"大倉委員","kind":"質問","question":"どういうふうな方向性を持っていこうかといったときの大きな分析の視点の１つになるのかなというところでは、工夫していだければなと思います。先ほどの単身のところもそうですが、そういったところも含めて伺いましたので、ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"若林委員","kind":"質問・要望","question":"この４つの要素の中で、今後あるべき理想というか、いわゆる安定した人口構造。それのためにこの４つの要素の中でどういうふうに優先順位をつけて注目をされていくのかというのを、今の段階で聞いておきたいと思います。","respondent":"柏原企画調整課長","answer":"他の委員から冒頭おっしゃっていただいたように、おっしゃっていただいたアンケートの手法とか、十分検討させていただければと考えています。そういった施策の捉え方といいますか、その４つの要素で言うと、そういう捉え方で行くんだろうなというふうに思ってあります。","id":"exchange-076"},{"speaker":"若林委員","kind":"提案","question":"それは当然出産のことですからありませんので、しっかりみんなで目標を共通にして、なかなか行けないのではないかと思います。今後どういうふうに区民とか議会に示しながら一緒に考えるというのか、またご提案も含めてという、ぜひの説明を求めました。","respondent":"柏原企画調整課長","answer":"１つは長期計画の検証の中で、どういう政策につなげるのかというお話は、報告させていただければと思っています。こういった機会を捉えて、こういった分析の状況であったりとかというのは、ご報告させていただければというふうに思っています。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/172349?Template=document&Id=6040#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":65391,"voices":184}},{"id":"h29-20171201-18","meetingId":"h29-cm12","date":"2017年12月1日","dateIso":"2017-12-01","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時５２分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"各競技強化選手等の施設使用料の免除","agenda":"各競技強化選手等の施設使用料の免除","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"２点ほどお伺いしたいのが、まず、ここに書かれている対象者についてです。一般の区民が予約しづらくなってしまうのかなと危惧しているのですけれども、その辺を、いかがお考えかということの説明を求めました。","respondent":"池田スポーツ推進課長","answer":"もう１つは各連盟にこういった取り組みがあるということを、ＰＲしていきたいと考えているところです。逆に区民の方と一緒にできれば、区民のスポーツレベルがさらに向上するのではないかと考えているところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"つまり、対象選手がもっと増える可能性もあるという理解でよろしいのかどうかということ。そういう選手は、逆に言えば、こういう場所では練習をしないで別の場所でやってくださいという認識でいいのかどうかの説明を求めました。","respondent":"池田スポーツ推進課長","answer":"例えば病気、身近な場所で練習をしていただき、リハビリが終わった段階でまたアスリートたちと一緒に練習するというようなことも想定しています。そして機運を醸成させていきたいという考えから、今回、使用料の免除をすることになりました。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"個人利用ということなのですけれども、先ほども質疑があったとおり、体育館で、例えば卓球など、そういう方がいたときに、特に球技ですが、練習は１人でなかなかできないような場合に、２人ぐらいでやるということも、個人利用という考え方でいいのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"あくまでもこちらの利用につきましては個人ですので、「３．対象者」に記載されている、指定選手に選ばれた方、東京アスリート選手などが無料です。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"１０人の該当者の中にいるかどうかわからないのですけれども、１人ではできないわけで、パートナーは有料だったら一緒にできるということなのですか。それとも、そういう人は走ったりとか運動したりとか、そういうことしかできない、球技はできないということなのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"現状はスケートボード場と弓道場の２カ所で、柔道、剣道といったような種目を考えているところです。こちらは練習をしてもらうということで、選手はもちろんですけれども、区民の方と一緒に練習をしていただくことを私どもは理想としています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"私もそこのところが疑問に思ったところで、選手には、例えばコーチ、また、マネジャーなどがいたり、チームの中で練習するということもあるのですけれども、指定された１人のみが免除で、一緒にいる人は有料になるということか尋ねました。","respondent":"池田スポーツ推進課長","answer":"登録をしていただき、使用料減額免除申請書で減免の申請をしていただいた後に免除という形をとらせていただきますので、アスリート本人が免除という形をとらせていただきます。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"カラオケ屋みたいに３人だと幾らとか４人だと幾らとか、どういう料金体系になるのかがちょっとわからないので、教えてください。それとも今後、条例改正などの手続が出てくるのか、そこについてもご説明いただきたいです。","respondent":"池田スポーツ推進課長","answer":"私の説明が不足しているかと思います。もう１つ、今回についても同様に行いますため、規則等の変更はございません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"東京２０２０大会はもう決まっているので、ではもう１段、ここは早目に対応していただきたい。やったよという感が強過ぎてしまって、見直しをするなら早目にしていただきたいなと思うので、それだけお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"質問","question":"意地悪な質問になってしまうかもしれないのですけれども、なかなか練習しづらい種目というのですか、水泳です。水泳には個人練習があるかもしれないが、その辺、ほんとうに簡単でいいです、時間がないので、簡単にご答弁ほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"そういったことでの異種というのですか、そういったもので利用されることについては、フリー利用の免除対象と考えているところです。東京アスリート認定選手のところでも、異種トレーニングをしていただくということでのフリー利用の免除ということを考えているところです。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645888?Template=document&Id=6526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":9489,"voices":38}},{"id":"h29-20171205-10","meetingId":"h29-cm12","date":"2017年12月5日","dateIso":"2017-12-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"会派、この中で第５条(1)、会派および議員は使用日の３か月前からグループウェアで予約できます。そういうことで提案しますので、ご検討のほどとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"その他の(3)の防災訓練のメールアドレスの件ですが、普通の携帯電話でも大丈夫なのか尋ねました。","respondent":"久保田区議会事務局長","answer":"確認しまして、普通の携帯電話でも大丈夫です。受信ができるようにしておいていただければ、クリックして押すことはできます。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問","question":"防災訓練なのですけれども、地域被害情報収集訓練に参加する会派の代表議員というのは、幹事長以外の誰かという認識でいいのか尋ねました。","respondent":"久保田区議会事務局長","answer":"そのとおりでございまして、各会派の中からお一人選んでいただいて、その方に今度シナリオをお渡しします。火災がどこどこであったというシナリオをお渡ししますので、それに基づいて送っていただきたいと思います。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"９月の議運でも本多委員から指摘があって、どちらかというと、非常に事態が悪化してしまっているのではないかという認識を持っております。いろいろこの間、そのところで、今回については起こってしまったことをどういうふうに捉えているかというところはどうか尋ねました。","respondent":"久保田区議会事務局長","answer":"議長から静止をしていただくけれども、それもやめなかったときには、今回は事務局の職員が直接傍聴席に行って注意をさせていただいたです。すぐには退場ではありませんけれども、入場前等にも厳重に、もう一度改めてお願いさせていただきたいと思ってあります。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"そうですか」と退場するかといえば、そういうときに、警備員の方の位置づけというか役割はどうなのでしょうか。そういうことで、警備の方はそういう部分で動いていただくことは難しいのか尋ねました。","respondent":"久保田区議会事務局長","answer":"そういった場合には、事務局から職員が行って、一緒になって対応することになると考えています。それでもちょっと指示に従わない場合は、警察にということもあるとは物の本にも書いてありますので、そういったことも想定はしています。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それをやってしまうと、議長の権限がなくなると思っているので、そこだけは気をつけていただきたい。あくまでも議長判断なので、そこら辺はと思ったので、意見だけ言っておきます。","respondent":"久保田区議会事務局長","answer":"私が説明したのは、事務局のこれまでの通例とか過去の例に見るとこういう流れであったということのご説明ですので、私どもが決めることではないです。すみません、申し訳ございませんでした。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"第４回定例会からタブレットが本格的に導入されまして、あさっての本会議もぜひ撮影をしていただきたいと要望します。議論ほしいと求めましたが、ホームページと議会だより等でぜひ発信をしてほしいと求めましたので、その点を。","respondent":"久保田区議会事務局長","answer":"編集を進めてありますので、これにつきましても、ご意見いただいたような形で進めていきたいと思ってあります。ホームページのほうは、適時そういったものは速報で出していきたいと思ってありますので、ご協力のほどよろしくお願いします。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5258#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":12621,"voices":47}},{"id":"h29-20171207-10","meetingId":"h29-cm12","date":"2017年12月7日","dateIso":"2017-12-07","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5260#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":728,"voices":7}}]);
